insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('d9c3da29-ee7f-4b37-adc0-9699a05d167a', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'Event Ecosystem, Types, and Stakeholders', 'This section gives students a map of the events industry and the relationships that make an event possible. The aim is to understand that different event purposes, ownership models, and stakeholder interests require different management choices.', 0),
  ('bac6e176-cec6-456f-b6e1-19400b958c0a', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'd9c3da29-ee7f-4b37-adc0-9699a05d167a', 'subtopic'::public.curated_course_node_type, 'Event typologies and business models', 'Students distinguish events by purpose, audience, ownership, scale, and revenue logic so they can choose suitable planning methods.', 0),
  ('84b8042f-fcb5-43cd-bcfb-3bfc936d0e0f', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'bac6e176-cec6-456f-b6e1-19400b958c0a', 'concept'::public.curated_course_node_type, 'Meetings, incentives, conferences, exhibitions, conventions, festivals, galas, weddings, sports, cultural, civic, and corporate events', null, 0),
  ('25daf038-c5e5-4282-a041-4811e244e5ec', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'bac6e176-cec6-456f-b6e1-19400b958c0a', 'concept'::public.curated_course_node_type, 'Hosted, ticketed, sponsored, association, government, nonprofit, and private events', null, 1),
  ('c91da90d-bd82-4a92-b3e5-ab2ad227f530', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'bac6e176-cec6-456f-b6e1-19400b958c0a', 'concept'::public.curated_course_node_type, 'Business-to-business, business-to-consumer, internal, public, and community-facing formats', null, 2),
  ('3b8d1a5b-4306-4a77-97a1-f12587c26ede', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'd9c3da29-ee7f-4b37-adc0-9699a05d167a', 'subtopic'::public.curated_course_node_type, 'Industry ecosystem and value chain', 'This subtopic shows how destinations, venues, organizers, agencies, suppliers, and hospitality partners create value together.', 1),
  ('b132aebb-50c1-402a-a2fd-613a3300280d', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '3b8d1a5b-4306-4a77-97a1-f12587c26ede', 'concept'::public.curated_course_node_type, 'Event owners, organizers, professional congress organizers, destination management companies, convention bureaus, and venue operators', null, 0),
  ('d88f93a3-cc4d-475e-bebe-14e9ec1c6b54', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '3b8d1a5b-4306-4a77-97a1-f12587c26ede', 'concept'::public.curated_course_node_type, 'Hotels, caterers, production companies, decorators, transportation providers, security, registration, and technology vendors', null, 1),
  ('b7a97059-8571-4896-b381-d092f60125b9', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '3b8d1a5b-4306-4a77-97a1-f12587c26ede', 'concept'::public.curated_course_node_type, 'Interdependencies, handoffs, service-level expectations, and total event experience', null, 2),
  ('737beeb2-8092-4af8-9c93-67f6708c343f', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'd9c3da29-ee7f-4b37-adc0-9699a05d167a', 'subtopic'::public.curated_course_node_type, 'Stakeholder analysis and governance', 'Students learn to identify influence, interests, decision rights, and communication needs before conflicts become operational problems.', 2),
  ('bc0c9abb-1d40-467d-8858-d96d9774a70b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '737beeb2-8092-4af8-9c93-67f6708c343f', 'concept'::public.curated_course_node_type, 'Sponsors, attendees, clients, exhibitors, speakers, residents, regulators, media, staff, and volunteers', null, 0),
  ('bef123d2-5d69-4593-9335-baf75c487f0a', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '737beeb2-8092-4af8-9c93-67f6708c343f', 'concept'::public.curated_course_node_type, 'Power–interest mapping and stakeholder salience', null, 1),
  ('486739b1-cc71-4afa-a836-aa26d832f95b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '737beeb2-8092-4af8-9c93-67f6708c343f', 'concept'::public.curated_course_node_type, 'Governance structures, decision rights, escalation paths, and advisory groups', null, 2),
  ('3b73bdf9-2915-495d-bb93-69c1103d7294', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'Needs Assessment, Strategy, Objectives, and Success Measures', 'Events should begin with a problem or opportunity—not a theme, venue, or menu. This section teaches students to convert stakeholder needs into a clear event strategy and measurable definition of success.', 1),
  ('fc37b082-dd54-4453-842f-3b4336218c60', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '3b73bdf9-2915-495d-bb93-69c1103d7294', 'subtopic'::public.curated_course_node_type, 'Discovery and needs assessment', 'Students learn to gather evidence about audiences, constraints, and desired change before designing the event.', 0),
  ('b2a3ee2a-2525-487a-9ffe-44f2af1056e9', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'fc37b082-dd54-4453-842f-3b4336218c60', 'concept'::public.curated_course_node_type, 'Client brief and discovery interview', null, 0),
  ('106f0205-f0a7-448c-b513-c337b9f3f59d', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'fc37b082-dd54-4453-842f-3b4336218c60', 'concept'::public.curated_course_node_type, 'Audience research, personas, journey data, and accessibility needs', null, 1),
  ('bc0dfbe3-533f-48ac-b937-64de6441868b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'fc37b082-dd54-4453-842f-3b4336218c60', 'concept'::public.curated_course_node_type, 'Environmental scan, prior-event evidence, assumptions, constraints, and feasibility', null, 2),
  ('494fb9f6-dedd-4419-a56c-af923debff15', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '3b73bdf9-2915-495d-bb93-69c1103d7294', 'subtopic'::public.curated_course_node_type, 'Purpose, goals, and objectives', 'This subtopic turns broad ambitions into decisions that guide budget, program, marketing, and evaluation.', 1),
  ('fcee603a-f030-4b44-8bec-2250d29e42dc', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '494fb9f6-dedd-4419-a56c-af923debff15', 'concept'::public.curated_course_node_type, 'Purpose statement, value proposition, and organizing principles', null, 0),
  ('e112c5ae-4259-4e84-9b42-84a5baf621d1', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '494fb9f6-dedd-4419-a56c-af923debff15', 'concept'::public.curated_course_node_type, 'SMART objectives and outcome hierarchy', null, 1),
  ('c77ea647-23f6-496c-9b8e-560329b0f293', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '494fb9f6-dedd-4419-a56c-af923debff15', 'concept'::public.curated_course_node_type, 'Alignment with organizational, destination, sponsor, and community strategy', null, 2),
  ('dbbba77c-59cf-4884-941d-c26d9b62a2c8', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '3b73bdf9-2915-495d-bb93-69c1103d7294', 'subtopic'::public.curated_course_node_type, 'Measurement architecture', 'Students define indicators early so registration systems, surveys, observation, and financial reports capture usable evidence.', 2),
  ('c4a90e6d-4951-48b0-bb2f-75e87a431d32', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'dbbba77c-59cf-4884-941d-c26d9b62a2c8', 'concept'::public.curated_course_node_type, 'Inputs, activities, outputs, outcomes, and impacts', null, 0),
  ('ac7d6a8f-ed6a-4d59-bf8f-52c18f3c86d0', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'dbbba77c-59cf-4884-941d-c26d9b62a2c8', 'concept'::public.curated_course_node_type, 'Key performance indicators, targets, baselines, and data sources', null, 1),
  ('8101362b-6119-4b15-8e80-c572ff211270', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'dbbba77c-59cf-4884-941d-c26d9b62a2c8', 'concept'::public.curated_course_node_type, 'Financial, learning, behavioral, experience, inclusion, sustainability, and legacy measures', null, 2),
  ('e4aad35b-e9c7-4ef8-a535-20cec257dfef', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'Project Management, Governance, and Planning Systems', 'This section provides the operating discipline that keeps thousands of tasks, dependencies, and decisions aligned. Students learn to build plans that are detailed enough to control execution but flexible enough to adapt.', 2),
  ('0c6aba08-efa7-499d-9110-dd0ec09d8cea', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'e4aad35b-e9c7-4ef8-a535-20cec257dfef', 'subtopic'::public.curated_course_node_type, 'Scope and work breakdown', 'Students translate the event concept into defined deliverables and manageable work packages.', 0),
  ('40908dce-f12a-4762-831f-1e07609e31c5', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '0c6aba08-efa7-499d-9110-dd0ec09d8cea', 'concept'::public.curated_course_node_type, 'Scope statement, assumptions, exclusions, and acceptance criteria', null, 0),
  ('0419054e-4d4b-467c-bf00-e351f8aaa1f5', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '0c6aba08-efa7-499d-9110-dd0ec09d8cea', 'concept'::public.curated_course_node_type, 'Work breakdown structure and deliverable decomposition', null, 1),
  ('22d109bf-9097-4c8c-80d0-8f1cf418f983', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '0c6aba08-efa7-499d-9110-dd0ec09d8cea', 'concept'::public.curated_course_node_type, 'Change control, scope creep, and version management', null, 2),
  ('b1f416e5-e84e-403a-b89a-d9d2bf70316b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'e4aad35b-e9c7-4ef8-a535-20cec257dfef', 'subtopic'::public.curated_course_node_type, 'Schedule and dependency management', 'This subtopic develops realistic sequencing from long-range milestones to minute-by-minute execution.', 1),
  ('446f0701-f421-4403-b281-75e6170b5eba', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'b1f416e5-e84e-403a-b89a-d9d2bf70316b', 'concept'::public.curated_course_node_type, 'Critical path, dependencies, lead times, buffers, and milestone plans', null, 0),
  ('883a09c2-62db-4f12-9e45-2dffd4fbd673', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'b1f416e5-e84e-403a-b89a-d9d2bf70316b', 'concept'::public.curated_course_node_type, 'Master timeline, production schedule, banquet event orders, and run of show', null, 1),
  ('80e380bc-39ff-4d82-8e54-b09223cf4e44', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'b1f416e5-e84e-403a-b89a-d9d2bf70316b', 'concept'::public.curated_course_node_type, 'Planning software, dashboards, document control, and status reporting', null, 2),
  ('f5ce5d20-49ac-4c0a-82ac-d984afc79103', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'e4aad35b-e9c7-4ef8-a535-20cec257dfef', 'subtopic'::public.curated_course_node_type, 'Roles, meetings, and decision systems', 'Students learn how clear ownership and disciplined communication reduce duplication and last-minute failure.', 2),
  ('c940769f-e86d-41f0-b788-4f3002029814', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'f5ce5d20-49ac-4c0a-82ac-d984afc79103', 'concept'::public.curated_course_node_type, 'RACI or responsibility matrix', null, 0),
  ('11efed3e-399d-4ed8-8703-628496743d00', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'f5ce5d20-49ac-4c0a-82ac-d984afc79103', 'concept'::public.curated_course_node_type, 'Planning cadence, agendas, minutes, action logs, and decision logs', null, 1),
  ('c6ff56b8-a2c0-4fe1-a795-283a92695e14', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'f5ce5d20-49ac-4c0a-82ac-d984afc79103', 'concept'::public.curated_course_node_type, 'Issue escalation, approvals, quality gates, and lessons tracking', null, 2),
  ('58d88b4c-5eca-48a3-96ff-d02db87bcb9b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'Financial Management, Pricing, Revenue, and Sponsorship', 'Events must deliver value within financial constraints. This section teaches students to build an auditable budget, manage cash and uncertainty, and develop ethical revenue strategies.', 3);
