  ('710dc3a3-0728-4026-876a-8fe81ef7765a', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '58d88b4c-5eca-48a3-96ff-d02db87bcb9b', 'subtopic'::public.curated_course_node_type, 'Budget development and control', 'Students create a living financial plan that connects scope, quantities, prices, taxes, service charges, and contingencies.', 0),
