  ('5c968570-9830-4b08-8edc-2a235610ff44', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '6f5630ae-3df4-413a-a256-41242b4e0429', 'concept'::public.curated_course_node_type, 'Registration tiers, early-bird pricing, yield, discounts, bundles, and refunds', null, 1),
  ('a7ded4c7-dbf3-4257-bbf1-f9b6ea3438bf', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '6f5630ae-3df4-413a-a256-41242b4e0429', 'concept'::public.curated_course_node_type, 'Ticketing, exhibits, merchandise, concessions, grants, and ancillary revenue', null, 2),
  ('bd2fa320-d1d7-490e-a6d5-24e80273ccd9', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '58d88b4c-5eca-48a3-96ff-d02db87bcb9b', 'subtopic'::public.curated_course_node_type, 'Sponsorship and partnership value', 'Students learn to create partnerships based on audience and mission fit rather than logo inventory alone.', 2),
  ('069d515b-b853-4a3a-beed-4d2c85e10ec0', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'bd2fa320-d1d7-490e-a6d5-24e80273ccd9', 'concept'::public.curated_course_node_type, 'Prospect research, rights inventory, valuation, and proposal design', null, 0),
  ('ef9c4317-bf50-4bcb-852a-05215b2344c6', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'bd2fa320-d1d7-490e-a6d5-24e80273ccd9', 'concept'::public.curated_course_node_type, 'Activation, exclusivity, category conflicts, and attendee trust', null, 1),
  ('69bfbdb9-d30f-4279-a5db-371201db1915', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'bd2fa320-d1d7-490e-a6d5-24e80273ccd9', 'concept'::public.curated_course_node_type, 'Deliverables tracking, fulfillment reports, and return on objectives', null, 2),
  ('1798853e-6b0a-40ae-b38e-e0523a58312f', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'Contracts, Procurement, Law, Ethics, and Compliance', 'This section prepares students to buy services responsibly and recognize when legal or specialist advice is needed. The emphasis is prevention, documentation, fair dealing, and informed risk allocation.', 4),
  ('2ed8cbd8-d6cb-435f-b508-0af59f8b12ca', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '1798853e-6b0a-40ae-b38e-e0523a58312f', 'subtopic'::public.curated_course_node_type, 'Strategic sourcing and procurement', 'Students learn to define needs, compare total value, and maintain a transparent supplier process.', 0),
  ('64e4d2cf-f823-4543-931c-5bb484c6f495', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '2ed8cbd8-d6cb-435f-b508-0af59f8b12ca', 'concept'::public.curated_course_node_type, 'Request for information, request for proposal, specifications, bid evaluation, and site visits', null, 0),
  ('a8c54ab2-3b4a-42a1-8eaa-1ee5669fe087', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '2ed8cbd8-d6cb-435f-b508-0af59f8b12ca', 'concept'::public.curated_course_node_type, 'Supplier due diligence, references, capacity, insurance, sustainability, accessibility, and labor practices', null, 1),
  ('3711df3c-de68-40b4-8806-96045625e385', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '2ed8cbd8-d6cb-435f-b508-0af59f8b12ca', 'concept'::public.curated_course_node_type, 'Negotiation strategy, best-value selection, conflicts of interest, and procurement records', null, 2),
  ('7e8cab12-5204-458d-83eb-2bc09bc3431f', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '1798853e-6b0a-40ae-b38e-e0523a58312f', 'subtopic'::public.curated_course_node_type, 'Contract fundamentals', 'This subtopic helps students read commercial terms and connect clauses to operational and financial exposure.', 1),
  ('de5f9454-740e-403d-a6c5-cc04dc5b1177', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '7e8cab12-5204-458d-83eb-2bc09bc3431f', 'concept'::public.curated_course_node_type, 'Scope, deliverables, price, payment, change orders, performance standards, and remedies', null, 0),
  ('6c0bbd4c-4399-426a-a847-c5e4b0a95379', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '7e8cab12-5204-458d-83eb-2bc09bc3431f', 'concept'::public.curated_course_node_type, 'Cancellation, attrition, rebooking, force majeure, indemnity, insurance, liability, and dispute resolution', null, 1),
  ('0cc049d8-ea39-44a2-a8bd-b923a53a860b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '7e8cab12-5204-458d-83eb-2bc09bc3431f', 'concept'::public.curated_course_node_type, 'Data processing, intellectual property, confidentiality, governing law, and international considerations', null, 2),
  ('eb09d085-64b0-4b0f-b15a-160875baec91', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '1798853e-6b0a-40ae-b38e-e0523a58312f', 'subtopic'::public.curated_course_node_type, 'Legal, ethical, and regulatory duties', 'Students identify common compliance areas while understanding that requirements vary by jurisdiction.', 2),
  ('88a3c7ec-b1cf-49cd-82ea-903e9ae4c4ad', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'eb09d085-64b0-4b0f-b15a-160875baec91', 'concept'::public.curated_course_node_type, 'Permits, occupancy, alcohol, food safety, music licensing, privacy, employment, tax, and accessibility law', null, 0),
  ('1371e272-47e0-4649-8289-6b02f327e9a5', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'eb09d085-64b0-4b0f-b15a-160875baec91', 'concept'::public.curated_course_node_type, 'Anti-bribery, gifts, transparency, truthful marketing, safeguarding, and codes of conduct', null, 1),
  ('f4e174c5-c417-40df-bc82-43d188619917', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'eb09d085-64b0-4b0f-b15a-160875baec91', 'concept'::public.curated_course_node_type, 'Duty of care, documentation, counsel referral, and ethical decision frameworks', null, 2),
  ('5501d429-b61d-4308-a02f-4c719980fcc8', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'Destination, Venue, Site Design, and Accessibility', 'The physical or virtual site shapes flow, safety, participation, cost, and brand perception. This section teaches students to select and configure environments using operational evidence and inclusive design.', 5),
  ('ee2730c3-a476-4177-8df1-b0a46b50e1fd', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '5501d429-b61d-4308-a02f-4c719980fcc8', 'subtopic'::public.curated_course_node_type, 'Destination and venue selection', 'Students assess fit across strategy, audience, access, cost, risk, capacity, and service capability.', 0),
  ('908de327-0ee3-4e1d-bfe5-1f88cd16226b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'ee2730c3-a476-4177-8df1-b0a46b50e1fd', 'concept'::public.curated_course_node_type, 'Destination appeal, seasonality, travel, visas, local partners, and community impacts', null, 0),
  ('1fc73c36-a1a5-4f10-a9bb-d8ed025da4d7', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'ee2730c3-a476-4177-8df1-b0a46b50e1fd', 'concept'::public.curated_course_node_type, 'Capacity, availability, room inventory, loading, back-of-house, utilities, connectivity, and labor conditions', null, 1),
  ('3b9af9f8-07d0-4ab3-b953-db3f6941717b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'ee2730c3-a476-4177-8df1-b0a46b50e1fd', 'concept'::public.curated_course_node_type, 'Site inspection checklist, weighted evaluation, total cost, and recommendation memo', null, 2),
  ('4344ac2b-fd3d-4458-8c93-fc7750a33a16', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '5501d429-b61d-4308-a02f-4c719980fcc8', 'subtopic'::public.curated_course_node_type, 'Space planning and attendee flow', 'This subtopic turns program requirements into safe, intuitive, and efficient layouts.', 1),
  ('eb9592c7-eb83-459f-8073-77691dd9cb69', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '4344ac2b-fd3d-4458-8c93-fc7750a33a16', 'concept'::public.curated_course_node_type, 'Room sets, sightlines, acoustics, staging, exhibits, queues, registration, and wayfinding', null, 0),
  ('80125910-fa19-4060-88e3-5db9fd05c53c', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '4344ac2b-fd3d-4458-8c93-fc7750a33a16', 'concept'::public.curated_course_node_type, 'Front-of-house, back-of-house, loading docks, storage, green rooms, and service corridors', null, 1),
  ('1a20c051-87ef-433e-a0b9-e2dea405e041', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '4344ac2b-fd3d-4458-8c93-fc7750a33a16', 'concept'::public.curated_course_node_type, 'Capacity calculations, circulation, crowd flow, egress, and temporary structures', null, 2),
  ('02fa04b5-dd26-4b06-95df-cbb1eb2a5386', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '5501d429-b61d-4308-a02f-4c719980fcc8', 'subtopic'::public.curated_course_node_type, 'Universal and inclusive design', 'Students design access proactively rather than treating accommodation as an exception.', 2),
  ('c3249a8c-60c5-46df-bd59-8795e1ea84c4', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '02fa04b5-dd26-4b06-95df-cbb1eb2a5386', 'concept'::public.curated_course_node_type, 'Step-free routes, seating choice, accessible toilets, transport, stages, and emergency egress', null, 0),
  ('57b912ab-35a3-407a-8c0b-8e47ef739833', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '02fa04b5-dd26-4b06-95df-cbb1eb2a5386', 'concept'::public.curated_course_node_type, 'Captioning, sign language, hearing support, sensory considerations, quiet rooms, lighting, and readable signage', null, 1),
  ('12dec647-ef6b-4c9c-bbdf-ca70f46cd47b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '02fa04b5-dd26-4b06-95df-cbb1eb2a5386', 'concept'::public.curated_course_node_type, 'Access statements, accommodation requests, service animals, companion support, and dignity', null, 2),
  ('247f9c72-f7b7-4193-b89f-a0520795fc22', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'Program Architecture, Experience Design, and Inclusion', 'Events compete for attention and participation. This section combines learning design, behavioral insight, hospitality, and inclusive practice to create coherent experiences that serve both purpose and people.', 6),
  ('5c1f2fe3-c206-46d3-9348-9cf56a553af1', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '247f9c72-f7b7-4193-b89f-a0520795fc22', 'subtopic'::public.curated_course_node_type, 'Program and content design', 'Students build a program narrative that balances outcomes, formats, pacing, and audience choice.', 0);
