values
  ('4f1dc2bf-01e4-4e6e-9b22-42b98a4e57ea', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '5c1f2fe3-c206-46d3-9348-9cf56a553af1', 'concept'::public.curated_course_node_type, 'Themes, content tracks, session architecture, abstracts, curation, and editorial standards', null, 0),
