  ('51adbd13-4348-4e1c-9124-75d2eb235473', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '247f9c72-f7b7-4193-b89f-a0520795fc22', 'subtopic'::public.curated_course_node_type, 'Attendee journey and service design', 'This subtopic maps the experience before, during, and after the event to remove friction and create meaningful moments.', 1),
  ('c7a4018c-afe1-4e01-8e7d-1949cd4718fd', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '51adbd13-4348-4e1c-9124-75d2eb235473', 'concept'::public.curated_course_node_type, 'Awareness, registration, preparation, arrival, participation, departure, and follow-up', null, 0),
  ('1cee96d4-1441-4bc5-84de-9e8bcb3d3acc', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '51adbd13-4348-4e1c-9124-75d2eb235473', 'concept'::public.curated_course_node_type, 'Journey maps, service blueprints, moments of truth, emotion, and recovery', null, 1),
  ('cba36420-f855-44ad-91f1-463c54066257', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '51adbd13-4348-4e1c-9124-75d2eb235473', 'concept'::public.curated_course_node_type, 'Personalization, hospitality standards, surprise and delight, and community building', null, 2),
  ('8727d245-1c01-488b-9b48-47917585695a', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '247f9c72-f7b7-4193-b89f-a0520795fc22', 'subtopic'::public.curated_course_node_type, 'Diversity, equity, inclusion, and belonging', 'Students learn to embed inclusion in representation, policy, purchasing, program design, and evaluation.', 2),
  ('5532b1e0-8354-4d02-993e-090d10f8e6be', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '8727d245-1c01-488b-9b48-47917585695a', 'concept'::public.curated_course_node_type, 'Inclusive speaker and supplier pipelines; fair compensation', null, 0),
  ('e532e2e2-378a-40d0-a025-a14c737bec05', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '8727d245-1c01-488b-9b48-47917585695a', 'concept'::public.curated_course_node_type, 'Pronouns, names, dress, family needs, faith practice, dietary needs, and anti-harassment expectations', null, 1),
  ('5c5cbb5d-ad93-4864-865a-5424d95b2d15', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '8727d245-1c01-488b-9b48-47917585695a', 'concept'::public.curated_course_node_type, 'Belonging, psychological safety, bystander response, reporting channels, and accountability', null, 2),
  ('2ca5d16d-ba18-4ebd-95c4-86c0e04a34d6', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'Food, Beverage, Catering, and Hospitality Operations', 'Food and beverage can be the largest operational and financial component of an event. Students learn to coordinate safe, inclusive, sustainable service that supports schedule and experience.', 7),
  ('2c3e70e3-e997-408c-9f04-b3c434e1d4dd', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '2ca5d16d-ba18-4ebd-95c4-86c0e04a34d6', 'subtopic'::public.curated_course_node_type, 'Menu and service planning', 'Students align menu, service style, quantity, timing, and presentation with audience and operational conditions.', 0),
  ('bd43a753-d81d-4c8b-8490-a273940995a3', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '2c3e70e3-e997-408c-9f04-b3c434e1d4dd', 'concept'::public.curated_course_node_type, 'Receptions, plated meals, buffets, stations, breaks, concessions, and off-premise catering', null, 0),
  ('766da982-6358-464d-8a0b-f8633c73a349', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '2c3e70e3-e997-408c-9f04-b3c434e1d4dd', 'concept'::public.curated_course_node_type, 'Guarantees, consumption, portions, pacing, staffing ratios, china, linen, and equipment', null, 1),
  ('cd9c0da9-6849-4930-a022-6e00bf036760', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '2c3e70e3-e997-408c-9f04-b3c434e1d4dd', 'concept'::public.curated_course_node_type, 'Local and seasonal sourcing, cultural fit, wellness, and brand expression', null, 2),
  ('3fa6fdf3-3639-486d-978b-bf7fea21f477', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '2ca5d16d-ba18-4ebd-95c4-86c0e04a34d6', 'subtopic'::public.curated_course_node_type, 'Dietary needs and food safety', 'This subtopic treats dietary inclusion and safety as critical risk and hospitality responsibilities.', 1),
  ('c9743712-7e98-4443-aa9b-d38a404ef54d', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '3fa6fdf3-3639-486d-978b-bf7fea21f477', 'concept'::public.curated_course_node_type, 'Allergies, intolerances, religious practices, ethical preferences, and clear labeling', null, 0),
  ('3a5fd535-fcc4-4044-8fe2-d4b13c209d43', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '3fa6fdf3-3639-486d-978b-bf7fea21f477', 'concept'::public.curated_course_node_type, 'Cross-contact prevention, temperature control, sanitation, traceability, and incident response', null, 1),
  ('6ef0d249-a3ef-46af-a67a-851dee21a129', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '3fa6fdf3-3639-486d-978b-bf7fea21f477', 'concept'::public.curated_course_node_type, 'Alcohol service, responsible service, age verification, and nonalcoholic parity', null, 2),
  ('f58058fe-b526-40db-bb6f-ace5680c5b90', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '2ca5d16d-ba18-4ebd-95c4-86c0e04a34d6', 'subtopic'::public.curated_course_node_type, 'Catering coordination and control', 'Students use documentation and communication to connect client intent with kitchen, service, venue, and production teams.', 2),
  ('5c7f3862-8d57-477f-8a89-1f8ffc820d87', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'f58058fe-b526-40db-bb6f-ace5680c5b90', 'concept'::public.curated_course_node_type, 'Banquet event orders, diagrams, tastings, guarantees, and change deadlines', null, 0),
  ('d7b5f048-d33d-4f8e-858a-eba37f4d9b9c', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'f58058fe-b526-40db-bb6f-ace5680c5b90', 'concept'::public.curated_course_node_type, 'Caterer–venue–planner handoffs and pre-conference meetings', null, 1),
  ('6f16b482-659b-4b5b-b485-847c47025c93', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'f58058fe-b526-40db-bb6f-ace5680c5b90', 'concept'::public.curated_course_node_type, 'Consumption reports, waste tracking, service recovery, and bill reconciliation', null, 2),
  ('6fa0f010-ecfd-4c90-9a97-90fde2b796b3', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'Production, Audiovisual, Event Technology, and Hybrid Delivery', 'Modern events are media and data environments as well as gatherings. This section prepares students to manage production partners, technology choices, digital delivery, and cyber risk without needing to become technicians.', 8),
  ('68fb4243-70b9-4392-85ec-298e200dab1c', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '6fa0f010-ecfd-4c90-9a97-90fde2b796b3', 'subtopic'::public.curated_course_node_type, 'Technical production and show calling', 'Students learn the language and workflows needed to coordinate staging, audio, video, lighting, power, rigging, and cues.', 0),
  ('05fbe831-70a3-4a98-be7f-4c6914d4f843', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '68fb4243-70b9-4392-85ec-298e200dab1c', 'concept'::public.curated_course_node_type, 'Production brief, technical drawings, equipment lists, labor calls, rehearsals, and cue sheets', null, 0),
  ('b78c8649-035d-4504-80ad-b42593c95ad4', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '68fb4243-70b9-4392-85ec-298e200dab1c', 'concept'::public.curated_course_node_type, 'Audio reinforcement, projection/LED, lighting, scenic, rigging, power, and redundancy', null, 1),
  ('bd6d3207-de96-4c4f-b35a-25c93d89895e', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '68fb4243-70b9-4392-85ec-298e200dab1c', 'concept'::public.curated_course_node_type, 'Producer, show caller, stage manager, technical director, operators, and speaker-ready room', null, 2),
  ('e8789d12-59a1-4ded-b46b-33a37b360c62', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '6fa0f010-ecfd-4c90-9a97-90fde2b796b3', 'subtopic'::public.curated_course_node_type, 'Event platforms and data systems', 'This subtopic connects technology selection to user needs, integration, support, privacy, and measurement.', 1),
  ('d85e00c3-f7fb-492a-bb1a-4617c2fd9daa', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'e8789d12-59a1-4ded-b46b-33a37b360c62', 'concept'::public.curated_course_node_type, 'Registration, mobile app, badge printing, lead retrieval, matchmaking, polling, streaming, and analytics', null, 0),
  ('fd5324d3-216b-4acb-8b08-e2f81f628690', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'e8789d12-59a1-4ded-b46b-33a37b360c62', 'concept'::public.curated_course_node_type, 'Requirements, demos, integrations, APIs, testing, support, service levels, and data portability', null, 1),
  ('339bb660-d12c-498b-876e-6bff1b7a6f6a', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'e8789d12-59a1-4ded-b46b-33a37b360c62', 'concept'::public.curated_course_node_type, 'Consent, data minimization, retention, access control, and privacy notices', null, 2),
  ('69f590b5-b866-4efa-b76c-aa706a07bec6', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '6fa0f010-ecfd-4c90-9a97-90fde2b796b3', 'subtopic'::public.curated_course_node_type, 'Virtual and hybrid experience', 'Students design equitable participation across rooms, screens, locations, and time zones.', 2),
  ('e27410f4-d48a-48d9-9255-e334bca7298c', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '69f590b5-b866-4efa-b76c-aa706a07bec6', 'concept'::public.curated_course_node_type, 'Format choice, remote speaker support, digital facilitation, and online networking', null, 0),
  ('9ab09ae1-fb9c-4b83-9754-89e1c9781393', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '69f590b5-b866-4efa-b76c-aa706a07bec6', 'concept'::public.curated_course_node_type, 'Content parity, interaction equity, captioning, moderation, and community management', null, 1),
  ('a9247efc-fd91-45ac-8755-86b419617609', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '69f590b5-b866-4efa-b76c-aa706a07bec6', 'concept'::public.curated_course_node_type, 'Bandwidth, latency, backups, recording rights, and platform contingency', null, 2),
  ('3d865870-461a-4ce2-8840-684aad09efbf', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '6fa0f010-ecfd-4c90-9a97-90fde2b796b3', 'subtopic'::public.curated_course_node_type, 'Cybersecurity and technology resilience', 'This subtopic introduces practical controls for protecting people, payments, content, and operations.', 3),
  ('cbf5adc4-21eb-4a24-9985-11d1984e4181', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '3d865870-461a-4ce2-8840-684aad09efbf', 'concept'::public.curated_course_node_type, 'Phishing, account takeover, payment fraud, ransomware, unauthorized access, and data leakage', null, 0),
  ('2cb330df-6381-440b-b3ac-7afac6f3012c', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '3d865870-461a-4ce2-8840-684aad09efbf', 'concept'::public.curated_course_node_type, 'Multi-factor authentication, least privilege, secure Wi-Fi, vendor review, backups, and incident escalation', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('f45e918e-cea5-49cc-a361-7bf1a13e1770', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '3d865870-461a-4ce2-8840-684aad09efbf', 'concept'::public.curated_course_node_type, 'Technology failure modes, offline procedures, spare equipment, and recovery priorities', null, 2),
  ('27d9a489-7020-487f-a797-1553323beb28', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'Marketing, Sales, Communications, and Registration', 'A strong event promise must reach the right people and be fulfilled throughout the attendee journey. Students learn integrated marketing, ethical persuasion, registration operations, and communication during routine and crisis conditions.', 9),
  ('0c8a935d-524e-4591-8fe2-aa69e0852704', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '27d9a489-7020-487f-a797-1553323beb28', 'subtopic'::public.curated_course_node_type, 'Audience strategy and event brand', 'Students define priority segments and a differentiated promise grounded in real audience value.', 0),
  ('6d8242f0-4f99-44d8-824c-87e8dd1396cc', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '0c8a935d-524e-4591-8fe2-aa69e0852704', 'concept'::public.curated_course_node_type, 'Segmentation, targeting, positioning, personas, and jobs-to-be-done', null, 0),
  ('e3308ed1-9fb6-4d93-b308-687b2bb3e7ae', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '0c8a935d-524e-4591-8fe2-aa69e0852704', 'concept'::public.curated_course_node_type, 'Name, theme, identity, messaging hierarchy, and brand standards', null, 1),
  ('59807703-b2a1-4fc4-a963-5cb1f4f2a918', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '0c8a935d-524e-4591-8fe2-aa69e0852704', 'concept'::public.curated_course_node_type, 'Competitive analysis, channel strategy, and campaign calendar', null, 2),
  ('5f396e38-f605-4e57-b572-7a610fab982e', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '27d9a489-7020-487f-a797-1553323beb28', 'subtopic'::public.curated_course_node_type, 'Promotion and sales conversion', 'This subtopic links content and channels to measurable acquisition, conversion, and retention.', 1),
  ('644f10b3-6083-4118-a5c0-adc709c73424', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '5f396e38-f605-4e57-b572-7a610fab982e', 'concept'::public.curated_course_node_type, 'Owned, earned, paid, partner, community, email, social, search, PR, and influencer channels', null, 0),
  ('77bb5a7f-26e1-44bd-a40d-f652d84a6c37', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '5f396e38-f605-4e57-b572-7a610fab982e', 'concept'::public.curated_course_node_type, 'Landing pages, calls to action, nurture, sales enablement, referrals, and retargeting', null, 1),
  ('18f0fa48-b8aa-42e4-9136-8e9246215c3b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '5f396e38-f605-4e57-b572-7a610fab982e', 'concept'::public.curated_course_node_type, 'Funnel metrics, attribution, acquisition cost, conversion, and consent-based marketing', null, 2),
  ('1a2eeac8-6e6d-4c1d-9969-3166d79673a1', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '27d9a489-7020-487f-a797-1553323beb28', 'subtopic'::public.curated_course_node_type, 'Registration and attendee communications', 'Students design accurate, accessible workflows from invitation through check-in and post-event follow-up.', 2),
  ('8231ea4a-b75e-4ae1-a5bb-2cf510a0513f', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '1a2eeac8-6e6d-4c1d-9969-3166d79673a1', 'concept'::public.curated_course_node_type, 'Registration fields, logic, payments, taxes, discounts, group registration, waitlists, transfers, and refunds', null, 0),
  ('52a92f28-f537-4070-b783-e1ec8a9365f8', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '1a2eeac8-6e6d-4c1d-9969-3166d79673a1', 'concept'::public.curated_course_node_type, 'Confirmation, pre-arrival, travel, access, agenda, mobile, push, SMS, and emergency messaging', null, 1),
  ('eb822001-5f87-4089-b755-ab3901c8ac15', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '1a2eeac8-6e6d-4c1d-9969-3166d79673a1', 'concept'::public.curated_course_node_type, 'Check-in, badge control, help desk, data quality, privacy, and service recovery', null, 2),
  ('9ce49d06-11ca-4e34-8fd4-8b227c4d141b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'Talent, Suppliers, Volunteers, and Team Leadership', 'Events rely on temporary, cross-organizational teams operating under time pressure. This section develops practical leadership for staffing, communication, training, welfare, performance, and partner relationships.', 10),
  ('76cef7fd-007a-48ce-ab0e-85fb12181f88', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '9ce49d06-11ca-4e34-8fd4-8b227c4d141b', 'subtopic'::public.curated_course_node_type, 'Workforce and talent planning', 'Students determine the roles, numbers, competencies, schedules, and support needed for delivery.', 0),
  ('69fd3fa1-4ba6-4051-b357-d7cc03e470e4', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '76cef7fd-007a-48ce-ab0e-85fb12181f88', 'concept'::public.curated_course_node_type, 'Leadership, planners, coordinators, speakers, performers, contractors, temporary staff, and volunteers', null, 0),
  ('10f46851-3188-4d73-9aad-2e0064de3e8c', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '76cef7fd-007a-48ce-ab0e-85fb12181f88', 'concept'::public.curated_course_node_type, 'Staffing plan, shift design, labor rules, credentials, uniforms, meals, transport, and accommodation', null, 1),
  ('42b3b671-8cb6-487f-a688-327efe56cb40', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '76cef7fd-007a-48ce-ab0e-85fb12181f88', 'concept'::public.curated_course_node_type, 'Inclusive recruitment, accessibility, background checks, and safeguarding where appropriate', null, 2),
  ('28ee55d4-a5b8-4758-90f5-df4a6d701526', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '9ce49d06-11ca-4e34-8fd4-8b227c4d141b', 'subtopic'::public.curated_course_node_type, 'Briefing, training, and performance', 'This subtopic turns a staffing list into a coordinated service team.', 1),
  ('9fed2cc6-dd78-447d-b592-0c0f3549c11b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '28ee55d4-a5b8-4758-90f5-df4a6d701526', 'concept'::public.curated_course_node_type, 'Orientation, role cards, standard operating procedures, scripts, maps, radios, and escalation routes', null, 0),
  ('a1b3db34-be35-4096-9aab-7432e2edfc3a', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '28ee55d4-a5b8-4758-90f5-df4a6d701526', 'concept'::public.curated_course_node_type, 'Tabletop exercises, rehearsals, simulations, and competency checks', null, 1),
  ('f4e946fc-4335-4cdf-ab2a-d8b8f1bbd8ca', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '28ee55d4-a5b8-4758-90f5-df4a6d701526', 'concept'::public.curated_course_node_type, 'Coaching, feedback, recognition, discipline, and post-shift debriefs', null, 2),
  ('521c05d9-f06c-4f0d-934b-01516d5c5555', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '9ce49d06-11ca-4e34-8fd4-8b227c4d141b', 'subtopic'::public.curated_course_node_type, 'Supplier and relationship management', 'Students learn to manage vendors as accountable partners while protecting scope, quality, and schedule.', 2),
  ('25a009aa-8a27-4f62-be7c-4d2f04fed69a', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '521c05d9-f06c-4f0d-934b-01516d5c5555', 'concept'::public.curated_course_node_type, 'Kickoff, communication protocols, submittals, samples, approvals, and progress reviews', null, 0),
  ('fefe6ba7-0332-45ce-a6b9-9fe18baab76a', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '521c05d9-f06c-4f0d-934b-01516d5c5555', 'concept'::public.curated_course_node_type, 'Key performance indicators, inspection, issue resolution, change control, and invoice approval', null, 1),
  ('a4a44801-7e3f-4753-9249-e09a1877ee06', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '521c05d9-f06c-4f0d-934b-01516d5c5555', 'concept'::public.curated_course_node_type, 'Relationship capital, ethical conduct, supplier diversity, and performance reviews', null, 2),
  ('b28b2996-3f45-4424-b0d9-330988ab467f', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'Risk, Safety, Security, Health, and Crowd Management', 'Events concentrate people, assets, and uncertainty. Students learn a proportionate, all-hazards approach that integrates prevention, preparedness, response, recovery, and clear command.', 11),
  ('18381423-34bb-489d-80b4-21163b21a3db', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'b28b2996-3f45-4424-b0d9-330988ab467f', 'subtopic'::public.curated_course_node_type, 'Risk assessment and treatment', 'Students identify hazards, analyze likelihood and consequence, assign owners, and choose controls.', 0),
  ('2cee9c13-9a1b-4a0e-9c25-ac2c75e55a5b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '18381423-34bb-489d-80b4-21163b21a3db', 'concept'::public.curated_course_node_type, 'Risk register, assumptions, triggers, interdependencies, and risk appetite', null, 0),
  ('c8e223c8-32ef-4e93-82e8-c925a4368fe8', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '18381423-34bb-489d-80b4-21163b21a3db', 'concept'::public.curated_course_node_type, 'Avoid, reduce, transfer, accept, monitor, and exploit opportunity', null, 1),
  ('59fdbb31-30a8-4026-9b52-6f2a79a8e7c2', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '18381423-34bb-489d-80b4-21163b21a3db', 'concept'::public.curated_course_node_type, 'Hierarchy of controls, residual risk, documentation, and review cadence', null, 2),
  ('fde7ef7a-2a82-4618-827f-3d48e81ac006', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'b28b2996-3f45-4424-b0d9-330988ab467f', 'subtopic'::public.curated_course_node_type, 'Safety, security, and safeguarding', 'This subtopic integrates legal duties, specialist advice, protective measures, and respectful participant care.', 1),
  ('4f3a9bdb-c5e9-4564-9e5b-0e4ba2519660', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'fde7ef7a-2a82-4618-827f-3d48e81ac006', 'concept'::public.curated_course_node_type, 'Fire and life safety, medical planning, weather, structures, electrical, food, alcohol, transport, and occupational safety', null, 0),
  ('3fb03920-0e04-4edd-91b7-cc1fa4e24464', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'fde7ef7a-2a82-4618-827f-3d48e81ac006', 'concept'::public.curated_course_node_type, 'Threat assessment, access control, credentialing, prohibited items, cash/assets, dignitary protection, and hostile acts', null, 1),
  ('8d4db194-8e2e-40a2-a0fc-2b51f093c59d', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'fde7ef7a-2a82-4618-827f-3d48e81ac006', 'concept'::public.curated_course_node_type, 'Safeguarding children and vulnerable participants; harassment and violence prevention', null, 2),
  ('4e387258-209f-4d79-8d6f-d9fc904c5188', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'b28b2996-3f45-4424-b0d9-330988ab467f', 'subtopic'::public.curated_course_node_type, 'Crowd management and emergency operations', 'Students learn to plan movement, communication, leadership, and continuity when conditions change quickly.', 2),
  ('b51d572b-cd0e-4336-bf8b-83dcb9a5a509', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '4e387258-209f-4d79-8d6f-d9fc904c5188', 'concept'::public.curated_course_node_type, 'Crowd profiles, density, ingress, egress, queues, barriers, front-of-stage, and behavior', null, 0),
  ('36cf9b09-7158-43b9-b95b-941fcf832b7c', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '4e387258-209f-4d79-8d6f-d9fc904c5188', 'concept'::public.curated_course_node_type, 'Emergency action plan, incident command, communications, evacuation, shelter-in-place, reunification, and accessibility', null, 1),
  ('235c2687-d153-49d0-97c0-4749aebbcd8c', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '4e387258-209f-4d79-8d6f-d9fc904c5188', 'concept'::public.curated_course_node_type, 'Crisis communication, business continuity, cancellation decisions, insurance notification, and after-action review', null, 2);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('1d31a298-f60a-4cc1-a977-cd0333c4d303', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'Sustainability, Social Impact, and Event Legacy', 'World-class events reduce harm and create value that lasts beyond closing time. This section aligns environmental management, responsible sourcing, inclusion, community benefit, and transparent measurement.', 12),
  ('732caa5a-4017-4670-9bf8-5cafa35b896f', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '1d31a298-f60a-4cc1-a977-cd0333c4d303', 'subtopic'::public.curated_course_node_type, 'Sustainability strategy and materiality', 'Students identify the most significant impacts and set achievable, measurable priorities.', 0),
  ('8ca66df1-ebd4-4ac8-89df-7830601e7dfa', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '732caa5a-4017-4670-9bf8-5cafa35b896f', 'concept'::public.curated_course_node_type, 'Policy, baseline, materiality assessment, targets, roles, and supplier requirements', null, 0),
  ('c1fa3d13-2570-46d4-8503-4eba3beb9f80', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '732caa5a-4017-4670-9bf8-5cafa35b896f', 'concept'::public.curated_course_node_type, 'Climate, energy, water, materials, food, mobility, biodiversity, and pollution', null, 1),
  ('eccef133-26d5-4394-a311-b751ac0ad1e3', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '732caa5a-4017-4670-9bf8-5cafa35b896f', 'concept'::public.curated_course_node_type, 'EIC Sustainable Event Standards, ISO 20121 concepts, and continuous improvement', null, 2),
  ('308e5bcd-3808-4e06-8f28-282d39cf8aad', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '1d31a298-f60a-4cc1-a977-cd0333c4d303', 'subtopic'::public.curated_course_node_type, 'Operational sustainability', 'This subtopic turns goals into procurement, production, catering, travel, and waste decisions.', 1),
  ('78324283-fb59-4d30-ace8-ebb88d8a4b3c', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '308e5bcd-3808-4e06-8f28-282d39cf8aad', 'concept'::public.curated_course_node_type, 'Avoidance before substitution, reuse, donation, recycling, composting, and circular design', null, 0),
  ('49d884c4-daa1-4ee3-bb6d-aaa986c5e326', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '308e5bcd-3808-4e06-8f28-282d39cf8aad', 'concept'::public.curated_course_node_type, 'Low-carbon travel, local sourcing, plant-forward menus, food rescue, refill systems, and efficient production', null, 1),
  ('b52c811b-f4d1-4932-baa3-65124b2a4f32', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '308e5bcd-3808-4e06-8f28-282d39cf8aad', 'concept'::public.curated_course_node_type, 'Measurement boundaries, waste audits, carbon estimates, documentation, and credible claims', null, 2),
  ('ebf0d37c-bb16-4338-9dab-5c86c1c941b0', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '1d31a298-f60a-4cc1-a977-cd0333c4d303', 'subtopic'::public.curated_course_node_type, 'Social impact and legacy', 'Students plan community value with local partners rather than assuming all event impacts are positive.', 2),
  ('46246b2b-be3a-4079-8a8c-6090e3bdffd6', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'ebf0d37c-bb16-4338-9dab-5c86c1c941b0', 'concept'::public.curated_course_node_type, 'Local hiring and purchasing, supplier diversity, accessibility, and fair labor', null, 0),
  ('55ff63ed-2c2b-4308-b450-760f60c867d9', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'ebf0d37c-bb16-4338-9dab-5c86c1c941b0', 'concept'::public.curated_course_node_type, 'Community consultation, cultural respect, displacement, overtourism, and resident experience', null, 1),
  ('5280d0aa-7fd4-4ee9-8306-ffc94050c92f', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'ebf0d37c-bb16-4338-9dab-5c86c1c941b0', 'concept'::public.curated_course_node_type, 'Volunteering, donations, knowledge transfer, destination legacy, and impact reporting', null, 2),
  ('b8c603b3-cfd9-4c7b-a420-cdb24e7e2af9', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', null, 'topic'::public.curated_course_node_type, 'On-Site Operations, Service Recovery, and Command', 'The live event is where plans meet reality. This section teaches students to coordinate people, information, spaces, supplies, and decisions through a shared operating picture.', 13),
  ('d6f0ae85-fb92-4e9c-971d-6b11ae633da0', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'b8c603b3-cfd9-4c7b-a420-cdb24e7e2af9', 'subtopic'::public.curated_course_node_type, 'Operational readiness and handover', 'Students verify that plans, people, spaces, systems, and approvals are ready before doors open.', 0),
  ('7a864c23-7480-40ce-8c0c-f0c70245e76b', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'd6f0ae85-fb92-4e9c-971d-6b11ae633da0', 'concept'::public.curated_course_node_type, 'Pre-event checklist, venue handover, inspections, permits, deliveries, installation, testing, and sign-off', null, 0),
  ('4fb30d6f-d3b3-419a-851f-989b02b0aa25', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'd6f0ae85-fb92-4e9c-971d-6b11ae633da0', 'concept'::public.curated_course_node_type, 'Pre-conference meeting, staff briefing, vendor check-in, contact lists, credentials, and keys', null, 1),
  ('3e60925b-31dc-4bf9-b52d-b5dcdebd6916', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'd6f0ae85-fb92-4e9c-971d-6b11ae633da0', 'concept'::public.curated_course_node_type, 'Operations center, radio plan, issue log, weather monitoring, and decision thresholds', null, 2),
  ('06861d85-1c52-4959-a4ef-65b5ad6b8567', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', 'b8c603b3-cfd9-4c7b-a420-cdb24e7e2af9', 'subtopic'::public.curated_course_node_type, 'Live event control', 'This subtopic focuses on situational awareness, timing, communication, quality, and disciplined adaptation.', 1),
  ('cd2cf1ef-1496-465a-a219-b22217d6278a', 'b9c0d1e2-3f4a-4b24-9c63-7d8e9f0a1b14', '06861d85-1c52-4959-a4ef-65b5ad6b8567', 'concept'::public.curated_course_node_type, 'Run of show, show call, room turns, attendance counts, queues, inventory, and VIP movements', null, 0),
