select
  'event-and-meeting-management',
  null,
  'Event and Meeting Management',
  'Event and Meeting Management',
  'This course prepares students to design, plan, sell, produce, operate, and evaluate meetings and events across hospitality settings. Students integrate event strategy, project management, finance, contracts, venue and destination analysis, program and experience design, catering, production, technology, marketing, registration, workforce leadership, risk, accessibility, sustainability, on-site command, and post-event evaluation. Through a semester-long client-style project and live operations simulations, students learn to make evidence-based decisions, coordinate diverse stakeholders, control scope and resources, protect participants, and deliver measurable value and positive impact.',
  $evntjson${"slug": "event-and-meeting-management", "title": "Event and Meeting Management", "description": "This course prepares students to design, plan, sell, produce, operate, and evaluate meetings and events across hospitality settings. Students integrate event strategy, project management, finance, contracts, venue and destination analysis, program and experience design, catering, production, technology, marketing, registration, workforce leadership, risk, accessibility, sustainability, on-site command, and post-event evaluation. Through a semester-long client-style project and live operations simulations, students learn to make evidence-based decisions, coordinate diverse stakeholders, control scope and resources, protect participants, and deliver measurable value and positive impact.", "topics": [{"id": "d9c3da29-ee7f-4b37-adc0-9699a05d167a", "type": "topic", "title": "Event Ecosystem, Types, and Stakeholders", "description": "This section gives students a map of the events industry and the relationships that make an event possible. The aim is to understand that different event purposes, ownership models, and stakeholder interests require different management choices.", "children": [{"id": "bac6e176-cec6-456f-b6e1-19400b958c0a", "type": "subtopic", "title": "Event typologies and business models", "children": [{"id": "84b8042f-fcb5-43cd-bcfb-3bfc936d0e0f", "type": "concept", "title": "Meetings, incentives, conferences, exhibitions, conventions, festivals, galas, weddings, sports, cultural, civic, and corporate events"}, {"id": "25daf038-c5e5-4282-a041-4811e244e5ec", "type": "concept", "title": "Hosted, ticketed, sponsored, association, government, nonprofit, and private events"}, {"id": "c91da90d-bd82-4a92-b3e5-ab2ad227f530", "type": "concept", "title": "Business-to-business, business-to-consumer, internal, public, and community-facing formats"}], "description": "Students distinguish events by purpose, audience, ownership, scale, and revenue logic so they can choose suitable planning methods."}, {"id": "3b8d1a5b-4306-4a77-97a1-f12587c26ede", "type": "subtopic", "title": "Industry ecosystem and value chain", "children": [{"id": "b132aebb-50c1-402a-a2fd-613a3300280d", "type": "concept", "title": "Event owners, organizers, professional congress organizers, destination management companies, convention bureaus, and venue operators"}, {"id": "d88f93a3-cc4d-475e-bebe-14e9ec1c6b54", "type": "concept", "title": "Hotels, caterers, production companies, decorators, transportation providers, security, registration, and technology vendors"}, {"id": "b7a97059-8571-4896-b381-d092f60125b9", "type": "concept", "title": "Interdependencies, handoffs, service-level expectations, and total event experience"}], "description": "This subtopic shows how destinations, venues, organizers, agencies, suppliers, and hospitality partners create value together."}, {"id": "737beeb2-8092-4af8-9c93-67f6708c343f", "type": "subtopic", "title": "Stakeholder analysis and governance", "children": [{"id": "bc0c9abb-1d40-467d-8858-d96d9774a70b", "type": "concept", "title": "Sponsors, attendees, clients, exhibitors, speakers, residents, regulators, media, staff, and volunteers"}, {"id": "bef123d2-5d69-4593-9335-baf75c487f0a", "type": "concept", "title": "Power–interest mapping and stakeholder salience"}, {"id": "486739b1-cc71-4afa-a836-aa26d832f95b", "type": "concept", "title": "Governance structures, decision rights, escalation paths, and advisory groups"}], "description": "Students learn to identify influence, interests, decision rights, and communication needs before conflicts become operational problems."}]}, {"id": "3b73bdf9-2915-495d-bb93-69c1103d7294", "type": "topic", "title": "Needs Assessment, Strategy, Objectives, and Success Measures", "description": "Events should begin with a problem or opportunity—not a theme, venue, or menu. This section teaches students to convert stakeholder needs into a clear event strategy and measurable definition of success.", "children": [{"id": "fc37b082-dd54-4453-842f-3b4336218c60", "type": "subtopic", "title": "Discovery and needs assessment", "children": [{"id": "b2a3ee2a-2525-487a-9ffe-44f2af1056e9", "type": "concept", "title": "Client brief and discovery interview"}, {"id": "106f0205-f0a7-448c-b513-c337b9f3f59d", "type": "concept", "title": "Audience research, personas, journey data, and accessibility needs"}, {"id": "bc0dfbe3-533f-48ac-b937-64de6441868b", "type": "concept", "title": "Environmental scan, prior-event evidence, assumptions, constraints, and feasibility"}], "description": "Students learn to gather evidence about audiences, constraints, and desired change before designing the event."}, {"id": "494fb9f6-dedd-4419-a56c-af923debff15", "type": "subtopic", "title": "Purpose, goals, and objectives", "children": [{"id": "fcee603a-f030-4b44-8bec-2250d29e42dc", "type": "concept", "title": "Purpose statement, value proposition, and organizing principles"}, {"id": "e112c5ae-4259-4e84-9b42-84a5baf621d1", "type": "concept", "title": "SMART objectives and outcome hierarchy"}, {"id": "c77ea647-23f6-496c-9b8e-560329b0f293", "type": "concept", "title": "Alignment with organizational, destination, sponsor, and community strategy"}], "description": "This subtopic turns broad ambitions into decisions that guide budget, program, marketing, and evaluation."}, {"id": "dbbba77c-59cf-4884-941d-c26d9b62a2c8", "type": "subtopic", "title": "Measurement architecture", "children": [{"id": "c4a90e6d-4951-48b0-bb2f-75e87a431d32", "type": "concept", "title": "Inputs, activities, outputs, outcomes, and impacts"}, {"id": "ac7d6a8f-ed6a-4d59-bf8f-52c18f3c86d0", "type": "concept", "title": "Key performance indicators, targets, baselines, and data sources"}, {"id": "8101362b-6119-4b15-8e80-c572ff211270", "type": "concept", "title": "Financial, learning, behavioral, experience, inclusion, sustainability, and legacy measures"}], "description": "Students define indicators early so registration systems, surveys, observation, and financial reports capture usable evidence."}]}, {"id": "e4aad35b-e9c7-4ef8-a535-20cec257dfef", "type": "topic", "title": "Project Management, Governance, and Planning Systems", "description": "This section provides the operating discipline that keeps thousands of tasks, dependencies, and decisions aligned. Students learn to build plans that are detailed enough to control execution but flexible enough to adapt.", "children": [{"id": "0c6aba08-efa7-499d-9110-dd0ec09d8cea", "type": "subtopic", "title": "Scope and work breakdown", "children": [{"id": "40908dce-f12a-4762-831f-1e07609e31c5", "type": "concept", "title": "Scope statement, assumptions, exclusions, and acceptance criteria"}, {"id": "0419054e-4d4b-467c-bf00-e351f8aaa1f5", "type": "concept", "title": "Work breakdown structure and deliverable decomposition"}, {"id": "22d109bf-9097-4c8c-80d0-8f1cf418f983", "type": "concept", "title": "Change control, scope creep, and version management"}], "description": "Students translate the event concept into defined deliverables and manageable work packages."}, {"id": "b1f416e5-e84e-403a-b89a-d9d2bf70316b", "type": "subtopic", "title": "Schedule and dependency management", "children": [{"id": "446f0701-f421-4403-b281-75e6170b5eba", "type": "concept", "title": "Critical path, dependencies, lead times, buffers, and milestone plans"}, {"id": "883a09c2-62db-4f12-9e45-2dffd4fbd673", "type": "concept", "title": "Master timeline, production schedule, banquet event orders, and run of show"}, {"id": "80e380bc-39ff-4d82-8e54-b09223cf4e44", "type": "concept", "title": "Planning software, dashboards, document control, and status reporting"}], "description": "This subtopic develops realistic sequencing from long-range milestones to minute-by-minute execution."}, {"id": "f5ce5d20-49ac-4c0a-82ac-d984afc79103", "type": "subtopic", "title": "Roles, meetings, and decision systems", "children": [{"id": "c940769f-e86d-41f0-b788-4f3002029814", "type": "concept", "title": "RACI or responsibility matrix"}, {"id": "11efed3e-399d-4ed8-8703-628496743d00", "type": "concept", "title": "Planning cadence, agendas, minutes, action logs, and decision logs"}, {"id": "c6ff56b8-a2c0-4fe1-a795-283a92695e14", "type": "concept", "title": "Issue escalation, approvals, quality gates, and lessons tracking"}], "description": "Students learn how clear ownership and disciplined communication reduce duplication and last-minute failure."}]}, {"id": "58d88b4c-5eca-48a3-96ff-d02db87bcb9b", "type": "topic", "title": "Financial Management, Pricing, Revenue, and Sponsorship", "description": "Events must deliver value within financial constraints. This section teaches students to build an auditable budget, manage cash and uncertainty, and develop ethical revenue strategies.", "children": [{"id": "710dc3a3-0728-4026-876a-8fe81ef7765a", "type": "subtopic", "title": "Budget development and control", "children": [{"id": "39eef547-2ea5-4d70-811c-7969936f4cdf", "type": "concept", "title": "Fixed, variable, direct, indirect, in-kind, and allocated costs"}, {"id": "f2f8b10e-1fbb-412c-ad55-a069453be295", "type": "concept", "title": "Quotes, purchase orders, commitments, accruals, actuals, and variance analysis"}, {"id": "e4ae391d-84d9-428c-855b-f197322cdc20", "type": "concept", "title": "Contingency reserves, cash flow, currency, tax, gratuity, and service charges"}], "description": "Students create a living financial plan that connects scope, quantities, prices, taxes, service charges, and contingencies."}, {"id": "6f5630ae-3df4-413a-a256-41242b4e0429", "type": "subtopic", "title": "Pricing and revenue management", "children": [{"id": "dd542eb1-7855-4b8b-8124-ec51b6ab2130", "type": "concept", "title": "Break-even, contribution margin, and cost-volume-profit analysis"}, {"id": "5c968570-9830-4b08-8edc-2a235610ff44", "type": "concept", "title": "Registration tiers, early-bird pricing, yield, discounts, bundles, and refunds"}, {"id": "a7ded4c7-dbf3-4257-bbf1-f9b6ea3438bf", "type": "concept", "title": "Ticketing, exhibits, merchandise, concessions, grants, and ancillary revenue"}], "description": "This subtopic explores how price, capacity, demand, and value shape attendance and financial performance."}, {"id": "bd2fa320-d1d7-490e-a6d5-24e80273ccd9", "type": "subtopic", "title": "Sponsorship and partnership value", "children": [{"id": "069d515b-b853-4a3a-beed-4d2c85e10ec0", "type": "concept", "title": "Prospect research, rights inventory, valuation, and proposal design"}, {"id": "ef9c4317-bf50-4bcb-852a-05215b2344c6", "type": "concept", "title": "Activation, exclusivity, category conflicts, and attendee trust"}, {"id": "69bfbdb9-d30f-4279-a5db-371201db1915", "type": "concept", "title": "Deliverables tracking, fulfillment reports, and return on objectives"}], "description": "Students learn to create partnerships based on audience and mission fit rather than logo inventory alone."}]}, {"id": "1798853e-6b0a-40ae-b38e-e0523a58312f", "type": "topic", "title": "Contracts, Procurement, Law, Ethics, and Compliance", "description": "This section prepares students to buy services responsibly and recognize when legal or specialist advice is needed. The emphasis is prevention, documentation, fair dealing, and informed risk allocation.", "children": [{"id": "2ed8cbd8-d6cb-435f-b508-0af59f8b12ca", "type": "subtopic", "title": "Strategic sourcing and procurement", "children": [{"id": "64e4d2cf-f823-4543-931c-5bb484c6f495", "type": "concept", "title": "Request for information, request for proposal, specifications, bid evaluation, and site visits"}, {"id": "a8c54ab2-3b4a-42a1-8eaa-1ee5669fe087", "type": "concept", "title": "Supplier due diligence, references, capacity, insurance, sustainability, accessibility, and labor practices"}, {"id": "3711df3c-de68-40b4-8806-96045625e385", "type": "concept", "title": "Negotiation strategy, best-value selection, conflicts of interest, and procurement records"}], "description": "Students learn to define needs, compare total value, and maintain a transparent supplier process."}, {"id": "7e8cab12-5204-458d-83eb-2bc09bc3431f", "type": "subtopic", "title": "Contract fundamentals", "children": [{"id": "de5f9454-740e-403d-a6c5-cc04dc5b1177", "type": "concept", "title": "Scope, deliverables, price, payment, change orders, performance standards, and remedies"}, {"id": "6c0bbd4c-4399-426a-a847-c5e4b0a95379", "type": "concept", "title": "Cancellation, attrition, rebooking, force majeure, indemnity, insurance, liability, and dispute resolution"}, {"id": "0cc049d8-ea39-44a2-a8bd-b923a53a860b", "type": "concept", "title": "Data processing, intellectual property, confidentiality, governing law, and international considerations"}], "description": "This subtopic helps students read commercial terms and connect clauses to operational and financial exposure."}, {"id": "eb09d085-64b0-4b0f-b15a-160875baec91", "type": "subtopic", "title": "Legal, ethical, and regulatory duties", "children": [{"id": "88a3c7ec-b1cf-49cd-82ea-903e9ae4c4ad", "type": "concept", "title": "Permits, occupancy, alcohol, food safety, music licensing, privacy, employment, tax, and accessibility law"}, {"id": "1371e272-47e0-4649-8289-6b02f327e9a5", "type": "concept", "title": "Anti-bribery, gifts, transparency, truthful marketing, safeguarding, and codes of conduct"}, {"id": "f4e174c5-c417-40df-bc82-43d188619917", "type": "concept", "title": "Duty of care, documentation, counsel referral, and ethical decision frameworks"}], "description": "Students identify common compliance areas while understanding that requirements vary by jurisdiction."}]}, {"id": "5501d429-b61d-4308-a02f-4c719980fcc8", "type": "topic", "title": "Destination, Venue, Site Design, and Accessibility", "description": "The physical or virtual site shapes flow, safety, participation, cost, and brand perception. This section teaches students to select and configure environments using operational evidence and inclusive design.", "children": [{"id": "ee2730c3-a476-4177-8df1-b0a46b50e1fd", "type": "subtopic", "title": "Destination and venue selection", "children": [{"id": "908de327-0ee3-4e1d-bfe5-1f88cd16226b", "type": "concept", "title": "Destination appeal, seasonality, travel, visas, local partners, and community impacts"}, {"id": "1fc73c36-a1a5-4f10-a9bb-d8ed025da4d7", "type": "concept", "title": "Capacity, availability, room inventory, loading, back-of-house, utilities, connectivity, and labor conditions"}, {"id": "3b9af9f8-07d0-4ab3-b953-db3f6941717b", "type": "concept", "title": "Site inspection checklist, weighted evaluation, total cost, and recommendation memo"}], "description": "Students assess fit across strategy, audience, access, cost, risk, capacity, and service capability."}, {"id": "4344ac2b-fd3d-4458-8c93-fc7750a33a16", "type": "subtopic", "title": "Space planning and attendee flow", "children": [{"id": "eb9592c7-eb83-459f-8073-77691dd9cb69", "type": "concept", "title": "Room sets, sightlines, acoustics, staging, exhibits, queues, registration, and wayfinding"}, {"id": "80125910-fa19-4060-88e3-5db9fd05c53c", "type": "concept", "title": "Front-of-house, back-of-house, loading docks, storage, green rooms, and service corridors"}, {"id": "1a20c051-87ef-433e-a0b9-e2dea405e041", "type": "concept", "title": "Capacity calculations, circulation, crowd flow, egress, and temporary structures"}], "description": "This subtopic turns program requirements into safe, intuitive, and efficient layouts."}, {"id": "02fa04b5-dd26-4b06-95df-cbb1eb2a5386", "type": "subtopic", "title": "Universal and inclusive design", "children": [{"id": "c3249a8c-60c5-46df-bd59-8795e1ea84c4", "type": "concept", "title": "Step-free routes, seating choice, accessible toilets, transport, stages, and emergency egress"}, {"id": "57b912ab-35a3-407a-8c0b-8e47ef739833", "type": "concept", "title": "Captioning, sign language, hearing support, sensory considerations, quiet rooms, lighting, and readable signage"}, {"id": "12dec647-ef6b-4c9c-bbdf-ca70f46cd47b", "type": "concept", "title": "Access statements, accommodation requests, service animals, companion support, and dignity"}], "description": "Students design access proactively rather than treating accommodation as an exception."}]}, {"id": "247f9c72-f7b7-4193-b89f-a0520795fc22", "type": "topic", "title": "Program Architecture, Experience Design, and Inclusion", "description": "Events compete for attention and participation. This section combines learning design, behavioral insight, hospitality, and inclusive practice to create coherent experiences that serve both purpose and people.", "children": [{"id": "5c1f2fe3-c206-46d3-9348-9cf56a553af1", "type": "subtopic", "title": "Program and content design", "children": [{"id": "4f1dc2bf-01e4-4e6e-9b22-42b98a4e57ea", "type": "concept", "title": "Themes, content tracks, session architecture, abstracts, curation, and editorial standards"}, {"id": "75b8b755-ee8e-46e8-a4e0-dbb882821bf5", "type": "concept", "title": "Keynotes, panels, workshops, peer learning, networking, performances, and ceremonies"}, {"id": "3b8cd8bb-4d36-4c09-b7f9-5f730638d23e", "type": "concept", "title": "Scheduling, transitions, breaks, attention, cognitive load, and content capture"}], "description": "Students build a program narrative that balances outcomes, formats, pacing, and audience choice."}, {"id": "51adbd13-4348-4e1c-9124-75d2eb235473", "type": "subtopic", "title": "Attendee journey and service design", "children": [{"id": "c7a4018c-afe1-4e01-8e7d-1949cd4718fd", "type": "concept", "title": "Awareness, registration, preparation, arrival, participation, departure, and follow-up"}, {"id": "1cee96d4-1441-4bc5-84de-9e8bcb3d3acc", "type": "concept", "title": "Journey maps, service blueprints, moments of truth, emotion, and recovery"}, {"id": "cba36420-f855-44ad-91f1-463c54066257", "type": "concept", "title": "Personalization, hospitality standards, surprise and delight, and community building"}], "description": "This subtopic maps the experience before, during, and after the event to remove friction and create meaningful moments."}, {"id": "8727d245-1c01-488b-9b48-47917585695a", "type": "subtopic", "title": "Diversity, equity, inclusion, and belonging", "children": [{"id": "5532b1e0-8354-4d02-993e-090d10f8e6be", "type": "concept", "title": "Inclusive speaker and supplier pipelines; fair compensation"}, {"id": "e532e2e2-378a-40d0-a025-a14c737bec05", "type": "concept", "title": "Pronouns, names, dress, family needs, faith practice, dietary needs, and anti-harassment expectations"}, {"id": "5c5cbb5d-ad93-4864-865a-5424d95b2d15", "type": "concept", "title": "Belonging, psychological safety, bystander response, reporting channels, and accountability"}], "description": "Students learn to embed inclusion in representation, policy, purchasing, program design, and evaluation."}]}, {"id": "2ca5d16d-ba18-4ebd-95c4-86c0e04a34d6", "type": "topic", "title": "Food, Beverage, Catering, and Hospitality Operations", "description": "Food and beverage can be the largest operational and financial component of an event. Students learn to coordinate safe, inclusive, sustainable service that supports schedule and experience.", "children": [{"id": "2c3e70e3-e997-408c-9f04-b3c434e1d4dd", "type": "subtopic", "title": "Menu and service planning", "children": [{"id": "bd43a753-d81d-4c8b-8490-a273940995a3", "type": "concept", "title": "Receptions, plated meals, buffets, stations, breaks, concessions, and off-premise catering"}, {"id": "766da982-6358-464d-8a0b-f8633c73a349", "type": "concept", "title": "Guarantees, consumption, portions, pacing, staffing ratios, china, linen, and equipment"}, {"id": "cd9c0da9-6849-4930-a022-6e00bf036760", "type": "concept", "title": "Local and seasonal sourcing, cultural fit, wellness, and brand expression"}], "description": "Students align menu, service style, quantity, timing, and presentation with audience and operational conditions."}, {"id": "3fa6fdf3-3639-486d-978b-bf7fea21f477", "type": "subtopic", "title": "Dietary needs and food safety", "children": [{"id": "c9743712-7e98-4443-aa9b-d38a404ef54d", "type": "concept", "title": "Allergies, intolerances, religious practices, ethical preferences, and clear labeling"}, {"id": "3a5fd535-fcc4-4044-8fe2-d4b13c209d43", "type": "concept", "title": "Cross-contact prevention, temperature control, sanitation, traceability, and incident response"}, {"id": "6ef0d249-a3ef-46af-a67a-851dee21a129", "type": "concept", "title": "Alcohol service, responsible service, age verification, and nonalcoholic parity"}], "description": "This subtopic treats dietary inclusion and safety as critical risk and hospitality responsibilities."}, {"id": "f58058fe-b526-40db-bb6f-ace5680c5b90", "type": "subtopic", "title": "Catering coordination and control", "children": [{"id": "5c7f3862-8d57-477f-8a89-1f8ffc820d87", "type": "concept", "title": "Banquet event orders, diagrams, tastings, guarantees, and change deadlines"}, {"id": "d7b5f048-d33d-4f8e-858a-eba37f4d9b9c", "type": "concept", "title": "Caterer–venue–planner handoffs and pre-conference meetings"}, {"id": "6f16b482-659b-4b5b-b485-847c47025c93", "type": "concept", "title": "Consumption reports, waste tracking, service recovery, and bill reconciliation"}], "description": "Students use documentation and communication to connect client intent with kitchen, service, venue, and production teams."}]}, {"id": "6fa0f010-ecfd-4c90-9a97-90fde2b796b3", "type": "topic", "title": "Production, Audiovisual, Event Technology, and Hybrid Delivery", "description": "Modern events are media and data environments as well as gatherings. This section prepares students to manage production partners, technology choices, digital delivery, and cyber risk without needing to become technicians.", "children": [{"id": "68fb4243-70b9-4392-85ec-298e200dab1c", "type": "subtopic", "title": "Technical production and show calling", "children": [{"id": "05fbe831-70a3-4a98-be7f-4c6914d4f843", "type": "concept", "title": "Production brief, technical drawings, equipment lists, labor calls, rehearsals, and cue sheets"}, {"id": "b78c8649-035d-4504-80ad-b42593c95ad4", "type": "concept", "title": "Audio reinforcement, projection/LED, lighting, scenic, rigging, power, and redundancy"}, {"id": "bd6d3207-de96-4c4f-b35a-25c93d89895e", "type": "concept", "title": "Producer, show caller, stage manager, technical director, operators, and speaker-ready room"}], "description": "Students learn the language and workflows needed to coordinate staging, audio, video, lighting, power, rigging, and cues."}, {"id": "e8789d12-59a1-4ded-b46b-33a37b360c62", "type": "subtopic", "title": "Event platforms and data systems", "children": [{"id": "d85e00c3-f7fb-492a-bb1a-4617c2fd9daa", "type": "concept", "title": "Registration, mobile app, badge printing, lead retrieval, matchmaking, polling, streaming, and analytics"}, {"id": "fd5324d3-216b-4acb-8b08-e2f81f628690", "type": "concept", "title": "Requirements, demos, integrations, APIs, testing, support, service levels, and data portability"}, {"id": "339bb660-d12c-498b-876e-6bff1b7a6f6a", "type": "concept", "title": "Consent, data minimization, retention, access control, and privacy notices"}], "description": "This subtopic connects technology selection to user needs, integration, support, privacy, and measurement."}, {"id": "69f590b5-b866-4efa-b76c-aa706a07bec6", "type": "subtopic", "title": "Virtual and hybrid experience", "children": [{"id": "e27410f4-d48a-48d9-9255-e334bca7298c", "type": "concept", "title": "Format choice, remote speaker support, digital facilitation, and online networking"}, {"id": "9ab09ae1-fb9c-4b83-9754-89e1c9781393", "type": "concept", "title": "Content parity, interaction equity, captioning, moderation, and community management"}, {"id": "a9247efc-fd91-45ac-8755-86b419617609", "type": "concept", "title": "Bandwidth, latency, backups, recording rights, and platform contingency"}], "description": "Students design equitable participation across rooms, screens, locations, and time zones."}, {"id": "3d865870-461a-4ce2-8840-684aad09efbf", "type": "subtopic", "title": "Cybersecurity and technology resilience", "children": [{"id": "cbf5adc4-21eb-4a24-9985-11d1984e4181", "type": "concept", "title": "Phishing, account takeover, payment fraud, ransomware, unauthorized access, and data leakage"}, {"id": "2cb330df-6381-440b-b3ac-7afac6f3012c", "type": "concept", "title": "Multi-factor authentication, least privilege, secure Wi-Fi, vendor review, backups, and incident escalation"}, {"id": "f45e918e-cea5-49cc-a361-7bf1a13e1770", "type": "concept", "title": "Technology failure modes, offline procedures, spare equipment, and recovery priorities"}], "description": "This subtopic introduces practical controls for protecting people, payments, content, and operations."}]}, {"id": "27d9a489-7020-487f-a797-1553323beb28", "type": "topic", "title": "Marketing, Sales, Communications, and Registration", "description": "A strong event promise must reach the right people and be fulfilled throughout the attendee journey. Students learn integrated marketing, ethical persuasion, registration operations, and communication during routine and crisis conditions.", "children": [{"id": "0c8a935d-524e-4591-8fe2-aa69e0852704", "type": "subtopic", "title": "Audience strategy and event brand", "children": [{"id": "6d8242f0-4f99-44d8-824c-87e8dd1396cc", "type": "concept", "title": "Segmentation, targeting, positioning, personas, and jobs-to-be-done"}, {"id": "e3308ed1-9fb6-4d93-b308-687b2bb3e7ae", "type": "concept", "title": "Name, theme, identity, messaging hierarchy, and brand standards"}, {"id": "59807703-b2a1-4fc4-a963-5cb1f4f2a918", "type": "concept", "title": "Competitive analysis, channel strategy, and campaign calendar"}], "description": "Students define priority segments and a differentiated promise grounded in real audience value."}, {"id": "5f396e38-f605-4e57-b572-7a610fab982e", "type": "subtopic", "title": "Promotion and sales conversion", "children": [{"id": "644f10b3-6083-4118-a5c0-adc709c73424", "type": "concept", "title": "Owned, earned, paid, partner, community, email, social, search, PR, and influencer channels"}, {"id": "77bb5a7f-26e1-44bd-a40d-f652d84a6c37", "type": "concept", "title": "Landing pages, calls to action, nurture, sales enablement, referrals, and retargeting"}, {"id": "18f0fa48-b8aa-42e4-9136-8e9246215c3b", "type": "concept", "title": "Funnel metrics, attribution, acquisition cost, conversion, and consent-based marketing"}], "description": "This subtopic links content and channels to measurable acquisition, conversion, and retention."}, {"id": "1a2eeac8-6e6d-4c1d-9969-3166d79673a1", "type": "subtopic", "title": "Registration and attendee communications", "children": [{"id": "8231ea4a-b75e-4ae1-a5bb-2cf510a0513f", "type": "concept", "title": "Registration fields, logic, payments, taxes, discounts, group registration, waitlists, transfers, and refunds"}, {"id": "52a92f28-f537-4070-b783-e1ec8a9365f8", "type": "concept", "title": "Confirmation, pre-arrival, travel, access, agenda, mobile, push, SMS, and emergency messaging"}, {"id": "eb822001-5f87-4089-b755-ab3901c8ac15", "type": "concept", "title": "Check-in, badge control, help desk, data quality, privacy, and service recovery"}], "description": "Students design accurate, accessible workflows from invitation through check-in and post-event follow-up."}]}, {"id": "9ce49d06-11ca-4e34-8fd4-8b227c4d141b", "type": "topic", "title": "Talent, Suppliers, Volunteers, and Team Leadership", "description": "Events rely on temporary, cross-organizational teams operating under time pressure. This section develops practical leadership for staffing, communication, training, welfare, performance, and partner relationships.", "children": [{"id": "76cef7fd-007a-48ce-ab0e-85fb12181f88", "type": "subtopic", "title": "Workforce and talent planning", "children": [{"id": "69fd3fa1-4ba6-4051-b357-d7cc03e470e4", "type": "concept", "title": "Leadership, planners, coordinators, speakers, performers, contractors, temporary staff, and volunteers"}, {"id": "10f46851-3188-4d73-9aad-2e0064de3e8c", "type": "concept", "title": "Staffing plan, shift design, labor rules, credentials, uniforms, meals, transport, and accommodation"}, {"id": "42b3b671-8cb6-487f-a688-327efe56cb40", "type": "concept", "title": "Inclusive recruitment, accessibility, background checks, and safeguarding where appropriate"}], "description": "Students determine the roles, numbers, competencies, schedules, and support needed for delivery."}, {"id": "28ee55d4-a5b8-4758-90f5-df4a6d701526", "type": "subtopic", "title": "Briefing, training, and performance", "children": [{"id": "9fed2cc6-dd78-447d-b592-0c0f3549c11b", "type": "concept", "title": "Orientation, role cards, standard operating procedures, scripts, maps, radios, and escalation routes"}, {"id": "a1b3db34-be35-4096-9aab-7432e2edfc3a", "type": "concept", "title": "Tabletop exercises, rehearsals, simulations, and competency checks"}, {"id": "f4e946fc-4335-4cdf-ab2a-d8b8f1bbd8ca", "type": "concept", "title": "Coaching, feedback, recognition, discipline, and post-shift debriefs"}], "description": "This subtopic turns a staffing list into a coordinated service team."}, {"id": "521c05d9-f06c-4f0d-934b-01516d5c5555", "type": "subtopic", "title": "Supplier and relationship management", "children": [{"id": "25a009aa-8a27-4f62-be7c-4d2f04fed69a", "type": "concept", "title": "Kickoff, communication protocols, submittals, samples, approvals, and progress reviews"}, {"id": "fefe6ba7-0332-45ce-a6b9-9fe18baab76a", "type": "concept", "title": "Key performance indicators, inspection, issue resolution, change control, and invoice approval"}, {"id": "a4a44801-7e3f-4753-9249-e09a1877ee06", "type": "concept", "title": "Relationship capital, ethical conduct, supplier diversity, and performance reviews"}], "description": "Students learn to manage vendors as accountable partners while protecting scope, quality, and schedule."}]}, {"id": "b28b2996-3f45-4424-b0d9-330988ab467f", "type": "topic", "title": "Risk, Safety, Security, Health, and Crowd Management", "description": "Events concentrate people, assets, and uncertainty. Students learn a proportionate, all-hazards approach that integrates prevention, preparedness, response, recovery, and clear command.", "children": [{"id": "18381423-34bb-489d-80b4-21163b21a3db", "type": "subtopic", "title": "Risk assessment and treatment", "children": [{"id": "2cee9c13-9a1b-4a0e-9c25-ac2c75e55a5b", "type": "concept", "title": "Risk register, assumptions, triggers, interdependencies, and risk appetite"}, {"id": "c8e223c8-32ef-4e93-82e8-c925a4368fe8", "type": "concept", "title": "Avoid, reduce, transfer, accept, monitor, and exploit opportunity"}, {"id": "59fdbb31-30a8-4026-9b52-6f2a79a8e7c2", "type": "concept", "title": "Hierarchy of controls, residual risk, documentation, and review cadence"}], "description": "Students identify hazards, analyze likelihood and consequence, assign owners, and choose controls."}, {"id": "fde7ef7a-2a82-4618-827f-3d48e81ac006", "type": "subtopic", "title": "Safety, security, and safeguarding", "children": [{"id": "4f3a9bdb-c5e9-4564-9e5b-0e4ba2519660", "type": "concept", "title": "Fire and life safety, medical planning, weather, structures, electrical, food, alcohol, transport, and occupational safety"}, {"id": "3fb03920-0e04-4edd-91b7-cc1fa4e24464", "type": "concept", "title": "Threat assessment, access control, credentialing, prohibited items, cash/assets, dignitary protection, and hostile acts"}, {"id": "8d4db194-8e2e-40a2-a0fc-2b51f093c59d", "type": "concept", "title": "Safeguarding children and vulnerable participants; harassment and violence prevention"}], "description": "This subtopic integrates legal duties, specialist advice, protective measures, and respectful participant care."}, {"id": "4e387258-209f-4d79-8d6f-d9fc904c5188", "type": "subtopic", "title": "Crowd management and emergency operations", "children": [{"id": "b51d572b-cd0e-4336-bf8b-83dcb9a5a509", "type": "concept", "title": "Crowd profiles, density, ingress, egress, queues, barriers, front-of-stage, and behavior"}, {"id": "36cf9b09-7158-43b9-b95b-941fcf832b7c", "type": "concept", "title": "Emergency action plan, incident command, communications, evacuation, shelter-in-place, reunification, and accessibility"}, {"id": "235c2687-d153-49d0-97c0-4749aebbcd8c", "type": "concept", "title": "Crisis communication, business continuity, cancellation decisions, insurance notification, and after-action review"}], "description": "Students learn to plan movement, communication, leadership, and continuity when conditions change quickly."}]}, {"id": "1d31a298-f60a-4cc1-a977-cd0333c4d303", "type": "topic", "title": "Sustainability, Social Impact, and Event Legacy", "description": "World-class events reduce harm and create value that lasts beyond closing time. This section aligns environmental management, responsible sourcing, inclusion, community benefit, and transparent measurement.", "children": [{"id": "732caa5a-4017-4670-9bf8-5cafa35b896f", "type": "subtopic", "title": "Sustainability strategy and materiality", "children": [{"id": "8ca66df1-ebd4-4ac8-89df-7830601e7dfa", "type": "concept", "title": "Policy, baseline, materiality assessment, targets, roles, and supplier requirements"}, {"id": "c1fa3d13-2570-46d4-8503-4eba3beb9f80", "type": "concept", "title": "Climate, energy, water, materials, food, mobility, biodiversity, and pollution"}, {"id": "eccef133-26d5-4394-a311-b751ac0ad1e3", "type": "concept", "title": "EIC Sustainable Event Standards, ISO 20121 concepts, and continuous improvement"}], "description": "Students identify the most significant impacts and set achievable, measurable priorities."}, {"id": "308e5bcd-3808-4e06-8f28-282d39cf8aad", "type": "subtopic", "title": "Operational sustainability", "children": [{"id": "78324283-fb59-4d30-ace8-ebb88d8a4b3c", "type": "concept", "title": "Avoidance before substitution, reuse, donation, recycling, composting, and circular design"}, {"id": "49d884c4-daa1-4ee3-bb6d-aaa986c5e326", "type": "concept", "title": "Low-carbon travel, local sourcing, plant-forward menus, food rescue, refill systems, and efficient production"}, {"id": "b52c811b-f4d1-4932-baa3-65124b2a4f32", "type": "concept", "title": "Measurement boundaries, waste audits, carbon estimates, documentation, and credible claims"}], "description": "This subtopic turns goals into procurement, production, catering, travel, and waste decisions."}, {"id": "ebf0d37c-bb16-4338-9dab-5c86c1c941b0", "type": "subtopic", "title": "Social impact and legacy", "children": [{"id": "46246b2b-be3a-4079-8a8c-6090e3bdffd6", "type": "concept", "title": "Local hiring and purchasing, supplier diversity, accessibility, and fair labor"}, {"id": "55ff63ed-2c2b-4308-b450-760f60c867d9", "type": "concept", "title": "Community consultation, cultural respect, displacement, overtourism, and resident experience"}, {"id": "5280d0aa-7fd4-4ee9-8306-ffc94050c92f", "type": "concept", "title": "Volunteering, donations, knowledge transfer, destination legacy, and impact reporting"}], "description": "Students plan community value with local partners rather than assuming all event impacts are positive."}]}, {"id": "b8c603b3-cfd9-4c7b-a420-cdb24e7e2af9", "type": "topic", "title": "On-Site Operations, Service Recovery, and Command", "description": "The live event is where plans meet reality. This section teaches students to coordinate people, information, spaces, supplies, and decisions through a shared operating picture.", "children": [{"id": "d6f0ae85-fb92-4e9c-971d-6b11ae633da0", "type": "subtopic", "title": "Operational readiness and handover", "children": [{"id": "7a864c23-7480-40ce-8c0c-f0c70245e76b", "type": "concept", "title": "Pre-event checklist, venue handover, inspections, permits, deliveries, installation, testing, and sign-off"}, {"id": "4fb30d6f-d3b3-419a-851f-989b02b0aa25", "type": "concept", "title": "Pre-conference meeting, staff briefing, vendor check-in, contact lists, credentials, and keys"}, {"id": "3e60925b-31dc-4bf9-b52d-b5dcdebd6916", "type": "concept", "title": "Operations center, radio plan, issue log, weather monitoring, and decision thresholds"}], "description": "Students verify that plans, people, spaces, systems, and approvals are ready before doors open."}, {"id": "06861d85-1c52-4959-a4ef-65b5ad6b8567", "type": "subtopic", "title": "Live event control", "children": [{"id": "cd2cf1ef-1496-465a-a219-b22217d6278a", "type": "concept", "title": "Run of show, show call, room turns, attendance counts, queues, inventory, and VIP movements"}, {"id": "8414766f-a8b4-44bd-916a-756894bd2d3d", "type": "concept", "title": "Command structure, radio etiquette, status reports, issue triage, and escalation"}, {"id": "25001057-b72e-404a-96ab-56c10ef7e152", "type": "concept", "title": "Change authorization, documentation, stakeholder updates, and continuity of guest experience"}], "description": "This subtopic focuses on situational awareness, timing, communication, quality, and disciplined adaptation."}, {"id": "04ae2820-4711-48aa-a237-6dcd3308651c", "type": "subtopic", "title": "Service recovery and closeout", "children": [{"id": "595e28c7-3259-4cfe-8516-297a73a3de33", "type": "concept", "title": "Listen, acknowledge, resolve, compensate within authority, document, and follow up"}, {"id": "e124a96d-6007-47ae-bee0-bc4a47df1dee", "type": "concept", "title": "Lost persons/property, complaints, access failures, speaker/vendor issues, and disruptions"}, {"id": "6917ed09-ce89-40e5-af8f-cc342210c36c", "type": "concept", "title": "Strike, damage inspection, rental return, reconciliation, staff welfare, and final handback"}], "description": "Students learn to recover trust during problems and close the site safely and accurately."}]}, {"id": "c20b75e9-2cb2-4e9c-863f-0fa314f4fd38", "type": "topic", "title": "Post-Event Evaluation, Reporting, and Continuous Improvement", "description": "Evaluation closes the management loop. Students learn to integrate experience, behavior, operations, finance, sustainability, and stakeholder value into decisions for future events.", "children": [{"id": "c0892e5b-a6c9-4b07-b46b-124db6de15dd", "type": "subtopic", "title": "Data collection and evidence quality", "children": [{"id": "5d232a11-493e-4576-8eb8-6c3d09b5feaf", "type": "concept", "title": "Registration and attendance data, financials, app/platform analytics, observation, interviews, surveys, and social listening"}, {"id": "643465e3-3565-4b87-bce5-0e2f330f3fa3", "type": "concept", "title": "Sampling, response bias, accessibility, privacy, data quality, and triangulation"}, {"id": "bba68630-3619-47da-8540-f7538e962f1d", "type": "concept", "title": "Real-time pulse checks, post-event windows, and longitudinal follow-up"}], "description": "Students select methods that are timely, proportionate, ethical, and capable of answering the event’s original questions."}, {"id": "61896c05-0bba-41f4-b1ed-1eff81a5e995", "type": "subtopic", "title": "Analysis and value communication", "children": [{"id": "d5a85c9d-2826-43e7-a107-71b9163921c4", "type": "concept", "title": "Actual versus objective, target, baseline, budget, and benchmark"}, {"id": "4c1d143d-090b-4010-931e-c7ac961a5138", "type": "concept", "title": "Satisfaction, Net Promoter Score limitations, learning, behavior, revenue, sponsor return, inclusion, sustainability, and legacy"}, {"id": "b64107a9-777b-4a5e-bbc6-f1153c389c3c", "type": "concept", "title": "Dashboards, executive summaries, sponsor reports, community reporting, and evidence-based narrative"}], "description": "This subtopic turns data into an honest account of performance, tradeoffs, and impact."}, {"id": "ada70d89-d32d-44e0-9521-5237c9f0ffe8", "type": "subtopic", "title": "Debrief and continuous improvement", "children": [{"id": "6a021b84-e662-46e6-96cc-a1f825571a1d", "type": "concept", "title": "Hot wash, structured debrief, supplier review, and psychological safety"}, {"id": "0b6c9e7f-f381-46ef-9aa4-c42f0ec1c253", "type": "concept", "title": "Root-cause analysis, corrective and preventive action, owners, deadlines, and verification"}, {"id": "688ff8e4-a2af-48cc-94e8-b3c148bf0c06", "type": "concept", "title": "Playbook updates, knowledge transfer, portfolio decisions, and next-event recommendations"}], "description": "Students convert lessons into owned improvements rather than storing them in a report no one uses."}]}], "dbBacked": true}$evntjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'event-and-meeting-management'
);

update public.learning_paths
set
  title = 'Event and Meeting Management',
  goal = 'Event and Meeting Management',
  summary = 'This course prepares students to design, plan, sell, produce, operate, and evaluate meetings and events across hospitality settings. Students integrate event strategy, project management, finance, contracts, venue and destination analysis, program and experience design, catering, production, technology, marketing, registration, workforce leadership, risk, accessibility, sustainability, on-site command, and post-event evaluation. Through a semester-long client-style project and live operations simulations, students learn to make evidence-based decisions, coordinate diverse stakeholders, control scope and resources, protect participants, and deliver measurable value and positive impact.',
  data = $evntjson${"slug": "event-and-meeting-management", "title": "Event and Meeting Management", "description": "This course prepares students to design, plan, sell, produce, operate, and evaluate meetings and events across hospitality settings. Students integrate event strategy, project management, finance, contracts, venue and destination analysis, program and experience design, catering, production, technology, marketing, registration, workforce leadership, risk, accessibility, sustainability, on-site command, and post-event evaluation. Through a semester-long client-style project and live operations simulations, students learn to make evidence-based decisions, coordinate diverse stakeholders, control scope and resources, protect participants, and deliver measurable value and positive impact.", "topics": [{"id": "d9c3da29-ee7f-4b37-adc0-9699a05d167a", "type": "topic", "title": "Event Ecosystem, Types, and Stakeholders", "description": "This section gives students a map of the events industry and the relationships that make an event possible. The aim is to understand that different event purposes, ownership models, and stakeholder interests require different management choices.", "children": [{"id": "bac6e176-cec6-456f-b6e1-19400b958c0a", "type": "subtopic", "title": "Event typologies and business models", "children": [{"id": "84b8042f-fcb5-43cd-bcfb-3bfc936d0e0f", "type": "concept", "title": "Meetings, incentives, conferences, exhibitions, conventions, festivals, galas, weddings, sports, cultural, civic, and corporate events"}, {"id": "25daf038-c5e5-4282-a041-4811e244e5ec", "type": "concept", "title": "Hosted, ticketed, sponsored, association, government, nonprofit, and private events"}, {"id": "c91da90d-bd82-4a92-b3e5-ab2ad227f530", "type": "concept", "title": "Business-to-business, business-to-consumer, internal, public, and community-facing formats"}], "description": "Students distinguish events by purpose, audience, ownership, scale, and revenue logic so they can choose suitable planning methods."}, {"id": "3b8d1a5b-4306-4a77-97a1-f12587c26ede", "type": "subtopic", "title": "Industry ecosystem and value chain", "children": [{"id": "b132aebb-50c1-402a-a2fd-613a3300280d", "type": "concept", "title": "Event owners, organizers, professional congress organizers, destination management companies, convention bureaus, and venue operators"}, {"id": "d88f93a3-cc4d-475e-bebe-14e9ec1c6b54", "type": "concept", "title": "Hotels, caterers, production companies, decorators, transportation providers, security, registration, and technology vendors"}, {"id": "b7a97059-8571-4896-b381-d092f60125b9", "type": "concept", "title": "Interdependencies, handoffs, service-level expectations, and total event experience"}], "description": "This subtopic shows how destinations, venues, organizers, agencies, suppliers, and hospitality partners create value together."}, {"id": "737beeb2-8092-4af8-9c93-67f6708c343f", "type": "subtopic", "title": "Stakeholder analysis and governance", "children": [{"id": "bc0c9abb-1d40-467d-8858-d96d9774a70b", "type": "concept", "title": "Sponsors, attendees, clients, exhibitors, speakers, residents, regulators, media, staff, and volunteers"}, {"id": "bef123d2-5d69-4593-9335-baf75c487f0a", "type": "concept", "title": "Power–interest mapping and stakeholder salience"}, {"id": "486739b1-cc71-4afa-a836-aa26d832f95b", "type": "concept", "title": "Governance structures, decision rights, escalation paths, and advisory groups"}], "description": "Students learn to identify influence, interests, decision rights, and communication needs before conflicts become operational problems."}]}, {"id": "3b73bdf9-2915-495d-bb93-69c1103d7294", "type": "topic", "title": "Needs Assessment, Strategy, Objectives, and Success Measures", "description": "Events should begin with a problem or opportunity—not a theme, venue, or menu. This section teaches students to convert stakeholder needs into a clear event strategy and measurable definition of success.", "children": [{"id": "fc37b082-dd54-4453-842f-3b4336218c60", "type": "subtopic", "title": "Discovery and needs assessment", "children": [{"id": "b2a3ee2a-2525-487a-9ffe-44f2af1056e9", "type": "concept", "title": "Client brief and discovery interview"}, {"id": "106f0205-f0a7-448c-b513-c337b9f3f59d", "type": "concept", "title": "Audience research, personas, journey data, and accessibility needs"}, {"id": "bc0dfbe3-533f-48ac-b937-64de6441868b", "type": "concept", "title": "Environmental scan, prior-event evidence, assumptions, constraints, and feasibility"}], "description": "Students learn to gather evidence about audiences, constraints, and desired change before designing the event."}, {"id": "494fb9f6-dedd-4419-a56c-af923debff15", "type": "subtopic", "title": "Purpose, goals, and objectives", "children": [{"id": "fcee603a-f030-4b44-8bec-2250d29e42dc", "type": "concept", "title": "Purpose statement, value proposition, and organizing principles"}, {"id": "e112c5ae-4259-4e84-9b42-84a5baf621d1", "type": "concept", "title": "SMART objectives and outcome hierarchy"}, {"id": "c77ea647-23f6-496c-9b8e-560329b0f293", "type": "concept", "title": "Alignment with organizational, destination, sponsor, and community strategy"}], "description": "This subtopic turns broad ambitions into decisions that guide budget, program, marketing, and evaluation."}, {"id": "dbbba77c-59cf-4884-941d-c26d9b62a2c8", "type": "subtopic", "title": "Measurement architecture", "children": [{"id": "c4a90e6d-4951-48b0-bb2f-75e87a431d32", "type": "concept", "title": "Inputs, activities, outputs, outcomes, and impacts"}, {"id": "ac7d6a8f-ed6a-4d59-bf8f-52c18f3c86d0", "type": "concept", "title": "Key performance indicators, targets, baselines, and data sources"}, {"id": "8101362b-6119-4b15-8e80-c572ff211270", "type": "concept", "title": "Financial, learning, behavioral, experience, inclusion, sustainability, and legacy measures"}], "description": "Students define indicators early so registration systems, surveys, observation, and financial reports capture usable evidence."}]}, {"id": "e4aad35b-e9c7-4ef8-a535-20cec257dfef", "type": "topic", "title": "Project Management, Governance, and Planning Systems", "description": "This section provides the operating discipline that keeps thousands of tasks, dependencies, and decisions aligned. Students learn to build plans that are detailed enough to control execution but flexible enough to adapt.", "children": [{"id": "0c6aba08-efa7-499d-9110-dd0ec09d8cea", "type": "subtopic", "title": "Scope and work breakdown", "children": [{"id": "40908dce-f12a-4762-831f-1e07609e31c5", "type": "concept", "title": "Scope statement, assumptions, exclusions, and acceptance criteria"}, {"id": "0419054e-4d4b-467c-bf00-e351f8aaa1f5", "type": "concept", "title": "Work breakdown structure and deliverable decomposition"}, {"id": "22d109bf-9097-4c8c-80d0-8f1cf418f983", "type": "concept", "title": "Change control, scope creep, and version management"}], "description": "Students translate the event concept into defined deliverables and manageable work packages."}, {"id": "b1f416e5-e84e-403a-b89a-d9d2bf70316b", "type": "subtopic", "title": "Schedule and dependency management", "children": [{"id": "446f0701-f421-4403-b281-75e6170b5eba", "type": "concept", "title": "Critical path, dependencies, lead times, buffers, and milestone plans"}, {"id": "883a09c2-62db-4f12-9e45-2dffd4fbd673", "type": "concept", "title": "Master timeline, production schedule, banquet event orders, and run of show"}, {"id": "80e380bc-39ff-4d82-8e54-b09223cf4e44", "type": "concept", "title": "Planning software, dashboards, document control, and status reporting"}], "description": "This subtopic develops realistic sequencing from long-range milestones to minute-by-minute execution."}, {"id": "f5ce5d20-49ac-4c0a-82ac-d984afc79103", "type": "subtopic", "title": "Roles, meetings, and decision systems", "children": [{"id": "c940769f-e86d-41f0-b788-4f3002029814", "type": "concept", "title": "RACI or responsibility matrix"}, {"id": "11efed3e-399d-4ed8-8703-628496743d00", "type": "concept", "title": "Planning cadence, agendas, minutes, action logs, and decision logs"}, {"id": "c6ff56b8-a2c0-4fe1-a795-283a92695e14", "type": "concept", "title": "Issue escalation, approvals, quality gates, and lessons tracking"}], "description": "Students learn how clear ownership and disciplined communication reduce duplication and last-minute failure."}]}, {"id": "58d88b4c-5eca-48a3-96ff-d02db87bcb9b", "type": "topic", "title": "Financial Management, Pricing, Revenue, and Sponsorship", "description": "Events must deliver value within financial constraints. This section teaches students to build an auditable budget, manage cash and uncertainty, and develop ethical revenue strategies.", "children": [{"id": "710dc3a3-0728-4026-876a-8fe81ef7765a", "type": "subtopic", "title": "Budget development and control", "children": [{"id": "39eef547-2ea5-4d70-811c-7969936f4cdf", "type": "concept", "title": "Fixed, variable, direct, indirect, in-kind, and allocated costs"}, {"id": "f2f8b10e-1fbb-412c-ad55-a069453be295", "type": "concept", "title": "Quotes, purchase orders, commitments, accruals, actuals, and variance analysis"}, {"id": "e4ae391d-84d9-428c-855b-f197322cdc20", "type": "concept", "title": "Contingency reserves, cash flow, currency, tax, gratuity, and service charges"}], "description": "Students create a living financial plan that connects scope, quantities, prices, taxes, service charges, and contingencies."}, {"id": "6f5630ae-3df4-413a-a256-41242b4e0429", "type": "subtopic", "title": "Pricing and revenue management", "children": [{"id": "dd542eb1-7855-4b8b-8124-ec51b6ab2130", "type": "concept", "title": "Break-even, contribution margin, and cost-volume-profit analysis"}, {"id": "5c968570-9830-4b08-8edc-2a235610ff44", "type": "concept", "title": "Registration tiers, early-bird pricing, yield, discounts, bundles, and refunds"}, {"id": "a7ded4c7-dbf3-4257-bbf1-f9b6ea3438bf", "type": "concept", "title": "Ticketing, exhibits, merchandise, concessions, grants, and ancillary revenue"}], "description": "This subtopic explores how price, capacity, demand, and value shape attendance and financial performance."}, {"id": "bd2fa320-d1d7-490e-a6d5-24e80273ccd9", "type": "subtopic", "title": "Sponsorship and partnership value", "children": [{"id": "069d515b-b853-4a3a-beed-4d2c85e10ec0", "type": "concept", "title": "Prospect research, rights inventory, valuation, and proposal design"}, {"id": "ef9c4317-bf50-4bcb-852a-05215b2344c6", "type": "concept", "title": "Activation, exclusivity, category conflicts, and attendee trust"}, {"id": "69bfbdb9-d30f-4279-a5db-371201db1915", "type": "concept", "title": "Deliverables tracking, fulfillment reports, and return on objectives"}], "description": "Students learn to create partnerships based on audience and mission fit rather than logo inventory alone."}]}, {"id": "1798853e-6b0a-40ae-b38e-e0523a58312f", "type": "topic", "title": "Contracts, Procurement, Law, Ethics, and Compliance", "description": "This section prepares students to buy services responsibly and recognize when legal or specialist advice is needed. The emphasis is prevention, documentation, fair dealing, and informed risk allocation.", "children": [{"id": "2ed8cbd8-d6cb-435f-b508-0af59f8b12ca", "type": "subtopic", "title": "Strategic sourcing and procurement", "children": [{"id": "64e4d2cf-f823-4543-931c-5bb484c6f495", "type": "concept", "title": "Request for information, request for proposal, specifications, bid evaluation, and site visits"}, {"id": "a8c54ab2-3b4a-42a1-8eaa-1ee5669fe087", "type": "concept", "title": "Supplier due diligence, references, capacity, insurance, sustainability, accessibility, and labor practices"}, {"id": "3711df3c-de68-40b4-8806-96045625e385", "type": "concept", "title": "Negotiation strategy, best-value selection, conflicts of interest, and procurement records"}], "description": "Students learn to define needs, compare total value, and maintain a transparent supplier process."}, {"id": "7e8cab12-5204-458d-83eb-2bc09bc3431f", "type": "subtopic", "title": "Contract fundamentals", "children": [{"id": "de5f9454-740e-403d-a6c5-cc04dc5b1177", "type": "concept", "title": "Scope, deliverables, price, payment, change orders, performance standards, and remedies"}, {"id": "6c0bbd4c-4399-426a-a847-c5e4b0a95379", "type": "concept", "title": "Cancellation, attrition, rebooking, force majeure, indemnity, insurance, liability, and dispute resolution"}, {"id": "0cc049d8-ea39-44a2-a8bd-b923a53a860b", "type": "concept", "title": "Data processing, intellectual property, confidentiality, governing law, and international considerations"}], "description": "This subtopic helps students read commercial terms and connect clauses to operational and financial exposure."}, {"id": "eb09d085-64b0-4b0f-b15a-160875baec91", "type": "subtopic", "title": "Legal, ethical, and regulatory duties", "children": [{"id": "88a3c7ec-b1cf-49cd-82ea-903e9ae4c4ad", "type": "concept", "title": "Permits, occupancy, alcohol, food safety, music licensing, privacy, employment, tax, and accessibility law"}, {"id": "1371e272-47e0-4649-8289-6b02f327e9a5", "type": "concept", "title": "Anti-bribery, gifts, transparency, truthful marketing, safeguarding, and codes of conduct"}, {"id": "f4e174c5-c417-40df-bc82-43d188619917", "type": "concept", "title": "Duty of care, documentation, counsel referral, and ethical decision frameworks"}], "description": "Students identify common compliance areas while understanding that requirements vary by jurisdiction."}]}, {"id": "5501d429-b61d-4308-a02f-4c719980fcc8", "type": "topic", "title": "Destination, Venue, Site Design, and Accessibility", "description": "The physical or virtual site shapes flow, safety, participation, cost, and brand perception. This section teaches students to select and configure environments using operational evidence and inclusive design.", "children": [{"id": "ee2730c3-a476-4177-8df1-b0a46b50e1fd", "type": "subtopic", "title": "Destination and venue selection", "children": [{"id": "908de327-0ee3-4e1d-bfe5-1f88cd16226b", "type": "concept", "title": "Destination appeal, seasonality, travel, visas, local partners, and community impacts"}, {"id": "1fc73c36-a1a5-4f10-a9bb-d8ed025da4d7", "type": "concept", "title": "Capacity, availability, room inventory, loading, back-of-house, utilities, connectivity, and labor conditions"}, {"id": "3b9af9f8-07d0-4ab3-b953-db3f6941717b", "type": "concept", "title": "Site inspection checklist, weighted evaluation, total cost, and recommendation memo"}], "description": "Students assess fit across strategy, audience, access, cost, risk, capacity, and service capability."}, {"id": "4344ac2b-fd3d-4458-8c93-fc7750a33a16", "type": "subtopic", "title": "Space planning and attendee flow", "children": [{"id": "eb9592c7-eb83-459f-8073-77691dd9cb69", "type": "concept", "title": "Room sets, sightlines, acoustics, staging, exhibits, queues, registration, and wayfinding"}, {"id": "80125910-fa19-4060-88e3-5db9fd05c53c", "type": "concept", "title": "Front-of-house, back-of-house, loading docks, storage, green rooms, and service corridors"}, {"id": "1a20c051-87ef-433e-a0b9-e2dea405e041", "type": "concept", "title": "Capacity calculations, circulation, crowd flow, egress, and temporary structures"}], "description": "This subtopic turns program requirements into safe, intuitive, and efficient layouts."}, {"id": "02fa04b5-dd26-4b06-95df-cbb1eb2a5386", "type": "subtopic", "title": "Universal and inclusive design", "children": [{"id": "c3249a8c-60c5-46df-bd59-8795e1ea84c4", "type": "concept", "title": "Step-free routes, seating choice, accessible toilets, transport, stages, and emergency egress"}, {"id": "57b912ab-35a3-407a-8c0b-8e47ef739833", "type": "concept", "title": "Captioning, sign language, hearing support, sensory considerations, quiet rooms, lighting, and readable signage"}, {"id": "12dec647-ef6b-4c9c-bbdf-ca70f46cd47b", "type": "concept", "title": "Access statements, accommodation requests, service animals, companion support, and dignity"}], "description": "Students design access proactively rather than treating accommodation as an exception."}]}, {"id": "247f9c72-f7b7-4193-b89f-a0520795fc22", "type": "topic", "title": "Program Architecture, Experience Design, and Inclusion", "description": "Events compete for attention and participation. This section combines learning design, behavioral insight, hospitality, and inclusive practice to create coherent experiences that serve both purpose and people.", "children": [{"id": "5c1f2fe3-c206-46d3-9348-9cf56a553af1", "type": "subtopic", "title": "Program and content design", "children": [{"id": "4f1dc2bf-01e4-4e6e-9b22-42b98a4e57ea", "type": "concept", "title": "Themes, content tracks, session architecture, abstracts, curation, and editorial standards"}, {"id": "75b8b755-ee8e-46e8-a4e0-dbb882821bf5", "type": "concept", "title": "Keynotes, panels, workshops, peer learning, networking, performances, and ceremonies"}, {"id": "3b8cd8bb-4d36-4c09-b7f9-5f730638d23e", "type": "concept", "title": "Scheduling, transitions, breaks, attention, cognitive load, and content capture"}], "description": "Students build a program narrative that balances outcomes, formats, pacing, and audience choice."}, {"id": "51adbd13-4348-4e1c-9124-75d2eb235473", "type": "subtopic", "title": "Attendee journey and service design", "children": [{"id": "c7a4018c-afe1-4e01-8e7d-1949cd4718fd", "type": "concept", "title": "Awareness, registration, preparation, arrival, participation, departure, and follow-up"}, {"id": "1cee96d4-1441-4bc5-84de-9e8bcb3d3acc", "type": "concept", "title": "Journey maps, service blueprints, moments of truth, emotion, and recovery"}, {"id": "cba36420-f855-44ad-91f1-463c54066257", "type": "concept", "title": "Personalization, hospitality standards, surprise and delight, and community building"}], "description": "This subtopic maps the experience before, during, and after the event to remove friction and create meaningful moments."}, {"id": "8727d245-1c01-488b-9b48-47917585695a", "type": "subtopic", "title": "Diversity, equity, inclusion, and belonging", "children": [{"id": "5532b1e0-8354-4d02-993e-090d10f8e6be", "type": "concept", "title": "Inclusive speaker and supplier pipelines; fair compensation"}, {"id": "e532e2e2-378a-40d0-a025-a14c737bec05", "type": "concept", "title": "Pronouns, names, dress, family needs, faith practice, dietary needs, and anti-harassment expectations"}, {"id": "5c5cbb5d-ad93-4864-865a-5424d95b2d15", "type": "concept", "title": "Belonging, psychological safety, bystander response, reporting channels, and accountability"}], "description": "Students learn to embed inclusion in representation, policy, purchasing, program design, and evaluation."}]}, {"id": "2ca5d16d-ba18-4ebd-95c4-86c0e04a34d6", "type": "topic", "title": "Food, Beverage, Catering, and Hospitality Operations", "description": "Food and beverage can be the largest operational and financial component of an event. Students learn to coordinate safe, inclusive, sustainable service that supports schedule and experience.", "children": [{"id": "2c3e70e3-e997-408c-9f04-b3c434e1d4dd", "type": "subtopic", "title": "Menu and service planning", "children": [{"id": "bd43a753-d81d-4c8b-8490-a273940995a3", "type": "concept", "title": "Receptions, plated meals, buffets, stations, breaks, concessions, and off-premise catering"}, {"id": "766da982-6358-464d-8a0b-f8633c73a349", "type": "concept", "title": "Guarantees, consumption, portions, pacing, staffing ratios, china, linen, and equipment"}, {"id": "cd9c0da9-6849-4930-a022-6e00bf036760", "type": "concept", "title": "Local and seasonal sourcing, cultural fit, wellness, and brand expression"}], "description": "Students align menu, service style, quantity, timing, and presentation with audience and operational conditions."}, {"id": "3fa6fdf3-3639-486d-978b-bf7fea21f477", "type": "subtopic", "title": "Dietary needs and food safety", "children": [{"id": "c9743712-7e98-4443-aa9b-d38a404ef54d", "type": "concept", "title": "Allergies, intolerances, religious practices, ethical preferences, and clear labeling"}, {"id": "3a5fd535-fcc4-4044-8fe2-d4b13c209d43", "type": "concept", "title": "Cross-contact prevention, temperature control, sanitation, traceability, and incident response"}, {"id": "6ef0d249-a3ef-46af-a67a-851dee21a129", "type": "concept", "title": "Alcohol service, responsible service, age verification, and nonalcoholic parity"}], "description": "This subtopic treats dietary inclusion and safety as critical risk and hospitality responsibilities."}, {"id": "f58058fe-b526-40db-bb6f-ace5680c5b90", "type": "subtopic", "title": "Catering coordination and control", "children": [{"id": "5c7f3862-8d57-477f-8a89-1f8ffc820d87", "type": "concept", "title": "Banquet event orders, diagrams, tastings, guarantees, and change deadlines"}, {"id": "d7b5f048-d33d-4f8e-858a-eba37f4d9b9c", "type": "concept", "title": "Caterer–venue–planner handoffs and pre-conference meetings"}, {"id": "6f16b482-659b-4b5b-b485-847c47025c93", "type": "concept", "title": "Consumption reports, waste tracking, service recovery, and bill reconciliation"}], "description": "Students use documentation and communication to connect client intent with kitchen, service, venue, and production teams."}]}, {"id": "6fa0f010-ecfd-4c90-9a97-90fde2b796b3", "type": "topic", "title": "Production, Audiovisual, Event Technology, and Hybrid Delivery", "description": "Modern events are media and data environments as well as gatherings. This section prepares students to manage production partners, technology choices, digital delivery, and cyber risk without needing to become technicians.", "children": [{"id": "68fb4243-70b9-4392-85ec-298e200dab1c", "type": "subtopic", "title": "Technical production and show calling", "children": [{"id": "05fbe831-70a3-4a98-be7f-4c6914d4f843", "type": "concept", "title": "Production brief, technical drawings, equipment lists, labor calls, rehearsals, and cue sheets"}, {"id": "b78c8649-035d-4504-80ad-b42593c95ad4", "type": "concept", "title": "Audio reinforcement, projection/LED, lighting, scenic, rigging, power, and redundancy"}, {"id": "bd6d3207-de96-4c4f-b35a-25c93d89895e", "type": "concept", "title": "Producer, show caller, stage manager, technical director, operators, and speaker-ready room"}], "description": "Students learn the language and workflows needed to coordinate staging, audio, video, lighting, power, rigging, and cues."}, {"id": "e8789d12-59a1-4ded-b46b-33a37b360c62", "type": "subtopic", "title": "Event platforms and data systems", "children": [{"id": "d85e00c3-f7fb-492a-bb1a-4617c2fd9daa", "type": "concept", "title": "Registration, mobile app, badge printing, lead retrieval, matchmaking, polling, streaming, and analytics"}, {"id": "fd5324d3-216b-4acb-8b08-e2f81f628690", "type": "concept", "title": "Requirements, demos, integrations, APIs, testing, support, service levels, and data portability"}, {"id": "339bb660-d12c-498b-876e-6bff1b7a6f6a", "type": "concept", "title": "Consent, data minimization, retention, access control, and privacy notices"}], "description": "This subtopic connects technology selection to user needs, integration, support, privacy, and measurement."}, {"id": "69f590b5-b866-4efa-b76c-aa706a07bec6", "type": "subtopic", "title": "Virtual and hybrid experience", "children": [{"id": "e27410f4-d48a-48d9-9255-e334bca7298c", "type": "concept", "title": "Format choice, remote speaker support, digital facilitation, and online networking"}, {"id": "9ab09ae1-fb9c-4b83-9754-89e1c9781393", "type": "concept", "title": "Content parity, interaction equity, captioning, moderation, and community management"}, {"id": "a9247efc-fd91-45ac-8755-86b419617609", "type": "concept", "title": "Bandwidth, latency, backups, recording rights, and platform contingency"}], "description": "Students design equitable participation across rooms, screens, locations, and time zones."}, {"id": "3d865870-461a-4ce2-8840-684aad09efbf", "type": "subtopic", "title": "Cybersecurity and technology resilience", "children": [{"id": "cbf5adc4-21eb-4a24-9985-11d1984e4181", "type": "concept", "title": "Phishing, account takeover, payment fraud, ransomware, unauthorized access, and data leakage"}, {"id": "2cb330df-6381-440b-b3ac-7afac6f3012c", "type": "concept", "title": "Multi-factor authentication, least privilege, secure Wi-Fi, vendor review, backups, and incident escalation"}, {"id": "f45e918e-cea5-49cc-a361-7bf1a13e1770", "type": "concept", "title": "Technology failure modes, offline procedures, spare equipment, and recovery priorities"}], "description": "This subtopic introduces practical controls for protecting people, payments, content, and operations."}]}, {"id": "27d9a489-7020-487f-a797-1553323beb28", "type": "topic", "title": "Marketing, Sales, Communications, and Registration", "description": "A strong event promise must reach the right people and be fulfilled throughout the attendee journey. Students learn integrated marketing, ethical persuasion, registration operations, and communication during routine and crisis conditions.", "children": [{"id": "0c8a935d-524e-4591-8fe2-aa69e0852704", "type": "subtopic", "title": "Audience strategy and event brand", "children": [{"id": "6d8242f0-4f99-44d8-824c-87e8dd1396cc", "type": "concept", "title": "Segmentation, targeting, positioning, personas, and jobs-to-be-done"}, {"id": "e3308ed1-9fb6-4d93-b308-687b2bb3e7ae", "type": "concept", "title": "Name, theme, identity, messaging hierarchy, and brand standards"}, {"id": "59807703-b2a1-4fc4-a963-5cb1f4f2a918", "type": "concept", "title": "Competitive analysis, channel strategy, and campaign calendar"}], "description": "Students define priority segments and a differentiated promise grounded in real audience value."}, {"id": "5f396e38-f605-4e57-b572-7a610fab982e", "type": "subtopic", "title": "Promotion and sales conversion", "children": [{"id": "644f10b3-6083-4118-a5c0-adc709c73424", "type": "concept", "title": "Owned, earned, paid, partner, community, email, social, search, PR, and influencer channels"}, {"id": "77bb5a7f-26e1-44bd-a40d-f652d84a6c37", "type": "concept", "title": "Landing pages, calls to action, nurture, sales enablement, referrals, and retargeting"}, {"id": "18f0fa48-b8aa-42e4-9136-8e9246215c3b", "type": "concept", "title": "Funnel metrics, attribution, acquisition cost, conversion, and consent-based marketing"}], "description": "This subtopic links content and channels to measurable acquisition, conversion, and retention."}, {"id": "1a2eeac8-6e6d-4c1d-9969-3166d79673a1", "type": "subtopic", "title": "Registration and attendee communications", "children": [{"id": "8231ea4a-b75e-4ae1-a5bb-2cf510a0513f", "type": "concept", "title": "Registration fields, logic, payments, taxes, discounts, group registration, waitlists, transfers, and refunds"}, {"id": "52a92f28-f537-4070-b783-e1ec8a9365f8", "type": "concept", "title": "Confirmation, pre-arrival, travel, access, agenda, mobile, push, SMS, and emergency messaging"}, {"id": "eb822001-5f87-4089-b755-ab3901c8ac15", "type": "concept", "title": "Check-in, badge control, help desk, data quality, privacy, and service recovery"}], "description": "Students design accurate, accessible workflows from invitation through check-in and post-event follow-up."}]}, {"id": "9ce49d06-11ca-4e34-8fd4-8b227c4d141b", "type": "topic", "title": "Talent, Suppliers, Volunteers, and Team Leadership", "description": "Events rely on temporary, cross-organizational teams operating under time pressure. This section develops practical leadership for staffing, communication, training, welfare, performance, and partner relationships.", "children": [{"id": "76cef7fd-007a-48ce-ab0e-85fb12181f88", "type": "subtopic", "title": "Workforce and talent planning", "children": [{"id": "69fd3fa1-4ba6-4051-b357-d7cc03e470e4", "type": "concept", "title": "Leadership, planners, coordinators, speakers, performers, contractors, temporary staff, and volunteers"}, {"id": "10f46851-3188-4d73-9aad-2e0064de3e8c", "type": "concept", "title": "Staffing plan, shift design, labor rules, credentials, uniforms, meals, transport, and accommodation"}, {"id": "42b3b671-8cb6-487f-a688-327efe56cb40", "type": "concept", "title": "Inclusive recruitment, accessibility, background checks, and safeguarding where appropriate"}], "description": "Students determine the roles, numbers, competencies, schedules, and support needed for delivery."}, {"id": "28ee55d4-a5b8-4758-90f5-df4a6d701526", "type": "subtopic", "title": "Briefing, training, and performance", "children": [{"id": "9fed2cc6-dd78-447d-b592-0c0f3549c11b", "type": "concept", "title": "Orientation, role cards, standard operating procedures, scripts, maps, radios, and escalation routes"}, {"id": "a1b3db34-be35-4096-9aab-7432e2edfc3a", "type": "concept", "title": "Tabletop exercises, rehearsals, simulations, and competency checks"}, {"id": "f4e946fc-4335-4cdf-ab2a-d8b8f1bbd8ca", "type": "concept", "title": "Coaching, feedback, recognition, discipline, and post-shift debriefs"}], "description": "This subtopic turns a staffing list into a coordinated service team."}, {"id": "521c05d9-f06c-4f0d-934b-01516d5c5555", "type": "subtopic", "title": "Supplier and relationship management", "children": [{"id": "25a009aa-8a27-4f62-be7c-4d2f04fed69a", "type": "concept", "title": "Kickoff, communication protocols, submittals, samples, approvals, and progress reviews"}, {"id": "fefe6ba7-0332-45ce-a6b9-9fe18baab76a", "type": "concept", "title": "Key performance indicators, inspection, issue resolution, change control, and invoice approval"}, {"id": "a4a44801-7e3f-4753-9249-e09a1877ee06", "type": "concept", "title": "Relationship capital, ethical conduct, supplier diversity, and performance reviews"}], "description": "Students learn to manage vendors as accountable partners while protecting scope, quality, and schedule."}]}, {"id": "b28b2996-3f45-4424-b0d9-330988ab467f", "type": "topic", "title": "Risk, Safety, Security, Health, and Crowd Management", "description": "Events concentrate people, assets, and uncertainty. Students learn a proportionate, all-hazards approach that integrates prevention, preparedness, response, recovery, and clear command.", "children": [{"id": "18381423-34bb-489d-80b4-21163b21a3db", "type": "subtopic", "title": "Risk assessment and treatment", "children": [{"id": "2cee9c13-9a1b-4a0e-9c25-ac2c75e55a5b", "type": "concept", "title": "Risk register, assumptions, triggers, interdependencies, and risk appetite"}, {"id": "c8e223c8-32ef-4e93-82e8-c925a4368fe8", "type": "concept", "title": "Avoid, reduce, transfer, accept, monitor, and exploit opportunity"}, {"id": "59fdbb31-30a8-4026-9b52-6f2a79a8e7c2", "type": "concept", "title": "Hierarchy of controls, residual risk, documentation, and review cadence"}], "description": "Students identify hazards, analyze likelihood and consequence, assign owners, and choose controls."}, {"id": "fde7ef7a-2a82-4618-827f-3d48e81ac006", "type": "subtopic", "title": "Safety, security, and safeguarding", "children": [{"id": "4f3a9bdb-c5e9-4564-9e5b-0e4ba2519660", "type": "concept", "title": "Fire and life safety, medical planning, weather, structures, electrical, food, alcohol, transport, and occupational safety"}, {"id": "3fb03920-0e04-4edd-91b7-cc1fa4e24464", "type": "concept", "title": "Threat assessment, access control, credentialing, prohibited items, cash/assets, dignitary protection, and hostile acts"}, {"id": "8d4db194-8e2e-40a2-a0fc-2b51f093c59d", "type": "concept", "title": "Safeguarding children and vulnerable participants; harassment and violence prevention"}], "description": "This subtopic integrates legal duties, specialist advice, protective measures, and respectful participant care."}, {"id": "4e387258-209f-4d79-8d6f-d9fc904c5188", "type": "subtopic", "title": "Crowd management and emergency operations", "children": [{"id": "b51d572b-cd0e-4336-bf8b-83dcb9a5a509", "type": "concept", "title": "Crowd profiles, density, ingress, egress, queues, barriers, front-of-stage, and behavior"}, {"id": "36cf9b09-7158-43b9-b95b-941fcf832b7c", "type": "concept", "title": "Emergency action plan, incident command, communications, evacuation, shelter-in-place, reunification, and accessibility"}, {"id": "235c2687-d153-49d0-97c0-4749aebbcd8c", "type": "concept", "title": "Crisis communication, business continuity, cancellation decisions, insurance notification, and after-action review"}], "description": "Students learn to plan movement, communication, leadership, and continuity when conditions change quickly."}]}, {"id": "1d31a298-f60a-4cc1-a977-cd0333c4d303", "type": "topic", "title": "Sustainability, Social Impact, and Event Legacy", "description": "World-class events reduce harm and create value that lasts beyond closing time. This section aligns environmental management, responsible sourcing, inclusion, community benefit, and transparent measurement.", "children": [{"id": "732caa5a-4017-4670-9bf8-5cafa35b896f", "type": "subtopic", "title": "Sustainability strategy and materiality", "children": [{"id": "8ca66df1-ebd4-4ac8-89df-7830601e7dfa", "type": "concept", "title": "Policy, baseline, materiality assessment, targets, roles, and supplier requirements"}, {"id": "c1fa3d13-2570-46d4-8503-4eba3beb9f80", "type": "concept", "title": "Climate, energy, water, materials, food, mobility, biodiversity, and pollution"}, {"id": "eccef133-26d5-4394-a311-b751ac0ad1e3", "type": "concept", "title": "EIC Sustainable Event Standards, ISO 20121 concepts, and continuous improvement"}], "description": "Students identify the most significant impacts and set achievable, measurable priorities."}, {"id": "308e5bcd-3808-4e06-8f28-282d39cf8aad", "type": "subtopic", "title": "Operational sustainability", "children": [{"id": "78324283-fb59-4d30-ace8-ebb88d8a4b3c", "type": "concept", "title": "Avoidance before substitution, reuse, donation, recycling, composting, and circular design"}, {"id": "49d884c4-daa1-4ee3-bb6d-aaa986c5e326", "type": "concept", "title": "Low-carbon travel, local sourcing, plant-forward menus, food rescue, refill systems, and efficient production"}, {"id": "b52c811b-f4d1-4932-baa3-65124b2a4f32", "type": "concept", "title": "Measurement boundaries, waste audits, carbon estimates, documentation, and credible claims"}], "description": "This subtopic turns goals into procurement, production, catering, travel, and waste decisions."}, {"id": "ebf0d37c-bb16-4338-9dab-5c86c1c941b0", "type": "subtopic", "title": "Social impact and legacy", "children": [{"id": "46246b2b-be3a-4079-8a8c-6090e3bdffd6", "type": "concept", "title": "Local hiring and purchasing, supplier diversity, accessibility, and fair labor"}, {"id": "55ff63ed-2c2b-4308-b450-760f60c867d9", "type": "concept", "title": "Community consultation, cultural respect, displacement, overtourism, and resident experience"}, {"id": "5280d0aa-7fd4-4ee9-8306-ffc94050c92f", "type": "concept", "title": "Volunteering, donations, knowledge transfer, destination legacy, and impact reporting"}], "description": "Students plan community value with local partners rather than assuming all event impacts are positive."}]}, {"id": "b8c603b3-cfd9-4c7b-a420-cdb24e7e2af9", "type": "topic", "title": "On-Site Operations, Service Recovery, and Command", "description": "The live event is where plans meet reality. This section teaches students to coordinate people, information, spaces, supplies, and decisions through a shared operating picture.", "children": [{"id": "d6f0ae85-fb92-4e9c-971d-6b11ae633da0", "type": "subtopic", "title": "Operational readiness and handover", "children": [{"id": "7a864c23-7480-40ce-8c0c-f0c70245e76b", "type": "concept", "title": "Pre-event checklist, venue handover, inspections, permits, deliveries, installation, testing, and sign-off"}, {"id": "4fb30d6f-d3b3-419a-851f-989b02b0aa25", "type": "concept", "title": "Pre-conference meeting, staff briefing, vendor check-in, contact lists, credentials, and keys"}, {"id": "3e60925b-31dc-4bf9-b52d-b5dcdebd6916", "type": "concept", "title": "Operations center, radio plan, issue log, weather monitoring, and decision thresholds"}], "description": "Students verify that plans, people, spaces, systems, and approvals are ready before doors open."}, {"id": "06861d85-1c52-4959-a4ef-65b5ad6b8567", "type": "subtopic", "title": "Live event control", "children": [{"id": "cd2cf1ef-1496-465a-a219-b22217d6278a", "type": "concept", "title": "Run of show, show call, room turns, attendance counts, queues, inventory, and VIP movements"}, {"id": "8414766f-a8b4-44bd-916a-756894bd2d3d", "type": "concept", "title": "Command structure, radio etiquette, status reports, issue triage, and escalation"}, {"id": "25001057-b72e-404a-96ab-56c10ef7e152", "type": "concept", "title": "Change authorization, documentation, stakeholder updates, and continuity of guest experience"}], "description": "This subtopic focuses on situational awareness, timing, communication, quality, and disciplined adaptation."}, {"id": "04ae2820-4711-48aa-a237-6dcd3308651c", "type": "subtopic", "title": "Service recovery and closeout", "children": [{"id": "595e28c7-3259-4cfe-8516-297a73a3de33", "type": "concept", "title": "Listen, acknowledge, resolve, compensate within authority, document, and follow up"}, {"id": "e124a96d-6007-47ae-bee0-bc4a47df1dee", "type": "concept", "title": "Lost persons/property, complaints, access failures, speaker/vendor issues, and disruptions"}, {"id": "6917ed09-ce89-40e5-af8f-cc342210c36c", "type": "concept", "title": "Strike, damage inspection, rental return, reconciliation, staff welfare, and final handback"}], "description": "Students learn to recover trust during problems and close the site safely and accurately."}]}, {"id": "c20b75e9-2cb2-4e9c-863f-0fa314f4fd38", "type": "topic", "title": "Post-Event Evaluation, Reporting, and Continuous Improvement", "description": "Evaluation closes the management loop. Students learn to integrate experience, behavior, operations, finance, sustainability, and stakeholder value into decisions for future events.", "children": [{"id": "c0892e5b-a6c9-4b07-b46b-124db6de15dd", "type": "subtopic", "title": "Data collection and evidence quality", "children": [{"id": "5d232a11-493e-4576-8eb8-6c3d09b5feaf", "type": "concept", "title": "Registration and attendance data, financials, app/platform analytics, observation, interviews, surveys, and social listening"}, {"id": "643465e3-3565-4b87-bce5-0e2f330f3fa3", "type": "concept", "title": "Sampling, response bias, accessibility, privacy, data quality, and triangulation"}, {"id": "bba68630-3619-47da-8540-f7538e962f1d", "type": "concept", "title": "Real-time pulse checks, post-event windows, and longitudinal follow-up"}], "description": "Students select methods that are timely, proportionate, ethical, and capable of answering the event’s original questions."}, {"id": "61896c05-0bba-41f4-b1ed-1eff81a5e995", "type": "subtopic", "title": "Analysis and value communication", "children": [{"id": "d5a85c9d-2826-43e7-a107-71b9163921c4", "type": "concept", "title": "Actual versus objective, target, baseline, budget, and benchmark"}, {"id": "4c1d143d-090b-4010-931e-c7ac961a5138", "type": "concept", "title": "Satisfaction, Net Promoter Score limitations, learning, behavior, revenue, sponsor return, inclusion, sustainability, and legacy"}, {"id": "b64107a9-777b-4a5e-bbc6-f1153c389c3c", "type": "concept", "title": "Dashboards, executive summaries, sponsor reports, community reporting, and evidence-based narrative"}], "description": "This subtopic turns data into an honest account of performance, tradeoffs, and impact."}, {"id": "ada70d89-d32d-44e0-9521-5237c9f0ffe8", "type": "subtopic", "title": "Debrief and continuous improvement", "children": [{"id": "6a021b84-e662-46e6-96cc-a1f825571a1d", "type": "concept", "title": "Hot wash, structured debrief, supplier review, and psychological safety"}, {"id": "0b6c9e7f-f381-46ef-9aa4-c42f0ec1c253", "type": "concept", "title": "Root-cause analysis, corrective and preventive action, owners, deadlines, and verification"}, {"id": "688ff8e4-a2af-48cc-94e8-b3c148bf0c06", "type": "concept", "title": "Playbook updates, knowledge transfer, portfolio decisions, and next-event recommendations"}], "description": "Students convert lessons into owned improvements rather than storing them in a report no one uses."}]}], "dbBacked": true}$evntjson$::jsonb,
